import { CacheDataLastTime } from 'domain/model/background'
import { TrustSite } from 'domain/model/trust-site'
import { useChromeStorageLocal } from 'hooks/chrome-storage-listener'
import { TRUST_SITE_CACHE_NAME } from 'shared/caches/trust-site'
import { getContentScriptCurrentUrl } from 'utils/location/get-content-script-current-url'

interface IIsADangerousSite {
  siteTrustInfo?: TrustSite
}

function hasUnknownAlert(data: TrustSite) {
  return (
    data?.domain?.alert_country_code ||
    data?.domain?.alert_creation ||
    data?.prediction?.alert_score
  )
}

function isDangerousUnknown(data: TrustSite) {
  return data?.result === 'UNKNOWN' && hasUnknownAlert(data)
}

export function isADangerousSite({ siteTrustInfo }: IIsADangerousSite) {
  if (siteTrustInfo) {
    return (
      siteTrustInfo?.result === 'UNSAFE' || isDangerousUnknown(siteTrustInfo)
    )
  }
}

export function useSiteDetector() {
  const { shortSubdomainExtracted } = getContentScriptCurrentUrl()
  const { currentData: trustSite } = useChromeStorageLocal<string>(
    TRUST_SITE_CACHE_NAME + shortSubdomainExtracted
  )

  const parsedData: CacheDataLastTime<TrustSite> = trustSite
    ? JSON.parse(trustSite)
    : { data: {} }

  return parsedData.data
}
