import { eventAdapter, EventAdapterTarget } from 'adapter/event-adapter'
import { ReactComponent as Icon } from 'assets/icons/settings.svg'
import {
  AreaLocation,
  ComponentLocation,
  EventOrigin,
} from 'domain/model/event'
import useAuth from 'hooks/auth/use'
import { useCallback, useState } from 'react'
import { useCompanyDiscounts } from 'scripts/pin-component/hooks/company-discounts'
import { getTimeWithNow } from 'shared/cache'
import { eventNamePrefix } from 'shared/gaEventsOrigin'
import { PIN_CONFIG_SILENCE_DURATION_CACHE_NAME } from 'shared/pinConfigCache'
import { getCurrentUrl } from 'utils/location/get-current-url'
import AnonymousOptions from './Anonymous'
import LoggedOptions from './Logged'
import * as S from './styles'

export const configurationOptionEventName = 'options_snooze'

export interface ConfigurationTriggerEventProps {
  event: string
  area: AreaLocation
}

function Configuration() {
  const [active, setActive] = useState(false)
  const { isAuthenticated } = useAuth()
  const { companyDiscounts } = useCompanyDiscounts()

  const silencePin = (time: number) => {
    localStorage.setItem(
      PIN_CONFIG_SILENCE_DURATION_CACHE_NAME,
      JSON.stringify(getTimeWithNow(time))
    )
    window.dispatchEvent(new Event('storage'))
    setActive(false)
  }

  const triggerEvent = useCallback(
    async ({ area, event }: ConfigurationTriggerEventProps) => {
      const active_url = await getCurrentUrl(EventOrigin.PIN)

      eventAdapter({
        target: EventAdapterTarget.current,
        data: {
          event: `${eventNamePrefix}${event}`,
          eventProps: {
            active_url,
            shortname: companyDiscounts?.company_info.short_name ?? '',
            company_name: companyDiscounts?.company_info.name ?? '',
            reputation:
              companyDiscounts?.company_info.general_reputation?.status ?? '',
            score:
              companyDiscounts?.company_info.general_reputation
                ?.average_score ?? '',
            ra_verificada:
              companyDiscounts?.company_info.company_flags.is_verified ?? false,
            component: ComponentLocation.MODAL_PIN,
            area,
          },
        },
      })
    },
    [
      companyDiscounts?.company_info.general_reputation?.average_score,
      companyDiscounts?.company_info.general_reputation?.status,
      companyDiscounts?.company_info.company_flags.is_verified,
      companyDiscounts?.company_info.name,
      companyDiscounts?.company_info.short_name,
    ]
  )

  return (
    <S.Main>
      <S.Settings
        active={active}
        onClick={async () => {
          await triggerEvent({
            event: 'open_snooze',
            area: AreaLocation.HEADER,
          })
          setActive(!active)
        }}
      >
        <Icon />
      </S.Settings>
      {active ? (
        <S.Modal>
          {isAuthenticated ? (
            <LoggedOptions
              setActive={setActive}
              silencePin={silencePin}
              triggerEvent={triggerEvent}
            />
          ) : (
            <AnonymousOptions
              setActive={setActive}
              silencePin={silencePin}
              triggerEvent={triggerEvent}
            />
          )}
        </S.Modal>
      ) : null}
    </S.Main>
  )
}

export default Configuration
