import { useEffect, useState } from 'react'
import { PROFILE_EXTENSION_PIN_CONFIG_SILENCE_DURATION_DEFAULT } from 'shared/cache'
import { PIN_CONFIG_SILENCE_DURATION_CACHE_NAME } from 'shared/pinConfigCache'
import { isDateExpired } from 'utils/dateHelper'
import { convertMinutesToMillies } from 'utils/timeHelper'

export function useSilencePin() {
  const [silencePin, setSilencePin] = useState<boolean>()

  const handleSilence = () => {
    const storageData = localStorage.getItem(
      PIN_CONFIG_SILENCE_DURATION_CACHE_NAME
    )

    const dataInMillies = storageData
      ? convertMinutesToMillies(Number(storageData))
      : PROFILE_EXTENSION_PIN_CONFIG_SILENCE_DURATION_DEFAULT

    if (isDateExpired(dataInMillies)) return setSilencePin(false)

    return setSilencePin(true)
  }

  useEffect(() => {
    function storageListener() {
      handleSilence()
    }
    window.addEventListener('storage', storageListener)

    return () => window.removeEventListener('storage', storageListener)
  }, [])

  useEffect(() => {
    handleSilence()
  }, [])

  return { silencePin }
}
