import { EventAdapterTarget, eventAdapter } from 'adapter/event-adapter'
import { DiscountsCompanyInfo } from 'domain/model/discounts/discounts-company-info'
import { Discount } from 'domain/model/discounts/main'
import { EventObject } from 'domain/model/event'
import { DiscountsService } from 'domain/services/discounts'
import { CuponeriaParamService } from 'domain/services/ParamService/Cuponeria/cuponeriaParamServiceParams'
import React, { useState } from 'react'
import { eventNamePrefix } from 'shared/gaEventsOrigin'
import { getCurrentUrl } from 'utils/location/get-current-url'
import openRedirectPage from 'utils/openRamaisRedirectPage'
import * as S from './styles'

interface CampaignEventObject extends EventObject {
  position: number
  totalDiscounts: number
}

interface OfferCardProps {
  companyInfo: DiscountsCompanyInfo
  offer: Discount
  storePath: string
  eventObject: CampaignEventObject
}

const OfferCard: React.FC<OfferCardProps> = ({
  companyInfo,
  offer,
  storePath,
  eventObject,
}) => {
  const [showRules, setShowRules] = useState(false)

  const toggleRules = async () => {
    const active_url = await getCurrentUrl(eventObject.eventOrigin)

    if (!showRules)
      eventAdapter({
        target: EventAdapterTarget.current,
        data: {
          event: `${eventNamePrefix}offer_rules`,
          eventProps: {
            active_url,
            shortname: companyInfo?.short_name ?? '',
            company_url: storePath ?? '',
            position: eventObject.position,
            total_discounts: eventObject.totalDiscounts,
            component: eventObject.componentLocation,
            area: eventObject.areaLocation,
          },
        },
      })

    setShowRules(!showRules)
  }

  const redirect = async () => {
    const active_url = await getCurrentUrl(eventObject.eventOrigin)

    eventAdapter({
      target: EventAdapterTarget.current,
      data: {
        event: `${eventNamePrefix}view_offer`,
        eventProps: {
          active_url,
          is_vcmo: offer?.is_vcmo ?? false,
          shortname: companyInfo?.short_name ?? '',
          company_name: companyInfo?.name ?? '',
          company_url: storePath ?? '',
          reputation: companyInfo?.general_reputation?.status ?? '',
          score: companyInfo?.general_reputation?.average_score ?? '',
          ra_verificada: companyInfo.company_flags.is_verified ?? false,
          offer_title: offer?.title ?? '',
          offer_rules: offer?.description ?? '',
          position: eventObject.position,
          total_discounts: eventObject.totalDiscounts,
          component: eventObject.componentLocation,
          area: eventObject.areaLocation,
        },
      },
    })

    const response = await DiscountsService.getRedirectUrl(offer.id)

    if (response?.link) {
      const redirectUrl =
        response.discount_source &&
        new CuponeriaParamService({
          url: response.link,
          value: 'reclame-aqui-ext',
        }).get()

      openRedirectPage({
        url: redirectUrl || response?.link,
        seller: companyInfo.name,
        sellerReputation: companyInfo.general_reputation,
        sellerLogoUrl: companyInfo.logo_url,
      })
      return
    }

    openRedirectPage({
      url: `https://${storePath}`,
      seller: companyInfo.name,
      sellerReputation: companyInfo.general_reputation,
      sellerLogoUrl: companyInfo.logo_url,
    })
  }

  return (
    <S.Main>
      <S.Header>
        <S.Title>{offer?.title ? offer.title : offer.description}</S.Title>
        <S.RedirectButton>
          <button onClick={redirect}>Ver oferta</button>
        </S.RedirectButton>
      </S.Header>
      <S.Line />
      <S.RulesContainer>
        <S.RulesHeader onClick={toggleRules}>
          <S.RuleTitle>Regras da oferta</S.RuleTitle>
          <S.ArrowIcon active={showRules} />
        </S.RulesHeader>
        {showRules && (
          <S.RulesDescription>{offer.description}</S.RulesDescription>
        )}
      </S.RulesContainer>
    </S.Main>
  )
}

export default OfferCard
