import { RavConfig, RavConfigRules } from 'domain/model/rav-config'
import { useCallback, useState } from 'react'
import { ravConfigListenerTypes } from 'scripts/long-live-message/listener-rules/rav-config-listener/get-listener'

let currentPort

export function useRavConfig() {
  const [data, setData] = useState<RavConfigRules>()

  const get = useCallback((reputation: string) => {
    let data: RavConfigRules | undefined
    currentPort = chrome.runtime.connect({ name: 'RAV_CONFIG' })
    currentPort.postMessage({
      type: ravConfigListenerTypes.getRavConfig,
    })
    currentPort.onMessage.addListener((response: RavConfig) => {
      const fiteredData = response.rules.find((r) =>
        r.ruleList.includes(reputation)
      )
      setData(fiteredData)
    })
    currentPort.onDisconnect.addListener(() => {
      currentPort = null
    })
    return data
  }, [])

  return { get, data }
}
