import { ReactNode, useEffect, useState } from 'react'
import NotificationContext from './context'
import {
  Banner as BannerInterface,
  Notification as NotificationInterface,
  NotificationState
} from './state'
import useAuth from 'hooks/auth/use'

interface NotificationProviderProps {
  children: ReactNode
}

let currentPort 

const NotificationProvider = ({ children }: NotificationProviderProps) => {
  const { isAuthenticated, token } = useAuth()

  const [notificationsState, setNotificationsState] =
    useState<NotificationInterface[]>()

  const [bannerState, setBannerState] =
    useState<BannerInterface[]>()

  useEffect(() => {
    getNotifications()
    getBanner()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [token])


  const getBanner = () => {
    currentPort = chrome.runtime.connect({ name: 'NOTIFICATIONS' })
    currentPort.postMessage({
        type: 'GET_BANNER',
      })
    currentPort.onMessage.addListener((data) => {
      setBannerState(data)
    })
    currentPort.onDisconnect.addListener(() => {
      currentPort = null
    })
  }

  const getNotifications = () => {
    if (!isAuthenticated) {
      return
    }
    
    currentPort = chrome.runtime.connect({ name: 'NOTIFICATIONS' })
    currentPort.postMessage({
        type: 'GET_NOTIFICATION',
      })
    currentPort.onMessage.addListener((data) => {
      setNotificationsState(data)
    })
    currentPort.onDisconnect.addListener(() => {
      currentPort = null
    })
  }

  const state: NotificationState = {
    banners: bannerState || [],
    notifications: notificationsState || [],
    fetchNotifications: getNotifications,
  }

  return (
    <NotificationContext.Provider value={state}>
      {children}
    </NotificationContext.Provider>
  )
}

export default NotificationProvider
