// eslint-disable-next-line @typescript-eslint/no-unused-vars
/*global chrome*/
import PinLayout from 'components/PinLayout'
import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import shadowRoot from 'react-shadow/styled-components'
import PinPage from './layout'
import { Provider } from './provider'

const PinMain = () => {
  return (
    <shadowRoot.section>
      <PinLayout>
        <Provider>
          <PinPage />
        </Provider>
      </PinLayout>
    </shadowRoot.section>
  )
}

const pinMainWrapper: HTMLElement = document.createElement(
  'reclameaqui-extension-pin'
)
document.body.appendChild(pinMainWrapper)

const extensionRoot = document.getElementById('extension-root')

const reactRoot = createRoot(pinMainWrapper!)

!extensionRoot &&
  reactRoot.render(
    <StrictMode>
      <PinMain />
    </StrictMode>
  )
