import { EventAdapterTarget, eventAdapter } from 'adapter/event-adapter'
import { AreaLocation, ComponentLocation } from 'domain/model/event'
import { useCompanyDiscounts } from 'scripts/pin-component/hooks/company-discounts'
import { eventNamePrefix } from 'shared/gaEventsOrigin'
import * as S from './styles'

interface ReputationGAEventProps {
  openModalState: boolean
}
function ReputationGAEvent({ openModalState }: ReputationGAEventProps) {
  const {
    companyDiscounts,
    couponsQuantity,
    offersQuantity,
    couponsAndOffersQuantity,
  } = useCompanyDiscounts()

  return (
    <S.Container
      onClick={() => {
        if (openModalState)
          eventAdapter({
            target: EventAdapterTarget.current,
            data: {
              event: `${eventNamePrefix}open_modal`,
              eventProps: {
                active_url: window.location.href,
                shortname: companyDiscounts?.company_info?.short_name,
                company_name: companyDiscounts?.company_info?.name,
                reputation:
                  companyDiscounts?.company_info.general_reputation?.status,
                score:
                  companyDiscounts?.company_info.general_reputation
                    .average_score,
                ra_verificada:
                  companyDiscounts?.company_info.company_flags?.is_verified,
                total_discounts: couponsAndOffersQuantity,
                coupons: couponsQuantity,
                offers: offersQuantity,
                component: ComponentLocation.PIN,
                area: AreaLocation.PIN_REPUTATION,
              },
            },
          })
      }}
    />
  )
}

export default ReputationGAEvent
