import { useEffect, useMemo } from 'react'
import * as C from '../components'
import { useCanShowPin } from '../hooks/CanShowPin'
import { useModal } from '../hooks/ModalProvider/use'
import { useWindowIsPopup } from '../hooks/WindowIsPopup'
import { isADangerousSite, useSiteDetector } from '../hooks/siteDetector'

const PinPage = () => {
  const { openModalState, closeModal } = useModal()

  const trustSite = useSiteDetector()

  // TODO: removendo temporariamente o detector de sites
  // const canShowDangerousPin = isADangerousSite({ siteTrustInfo: trustSite })
  const canShowDangerousPin = false
  const { windowIsPopup } = useWindowIsPopup()

  const canShowPin = useCanShowPin({
    isDangerous: canShowDangerousPin,
    windowIsPopup,
  })

  const canShowModal = useMemo(() => {
    return openModalState
  }, [openModalState])

  useEffect(() => {
    if (!canShowPin) closeModal?.()
  }, [canShowPin, closeModal])

  return (
    <>
      {canShowPin ? <C.Pin /> : null}
      {canShowDangerousPin ? (
        <C.PinWarning
          status={trustSite.result}
          warning={trustSite.alerts.length}
        />
      ) : null}
      {canShowModal &&
        (canShowDangerousPin ? (
          <C.ModalWarning status={trustSite.result} alerts={trustSite.alerts} />
        ) : (
          <C.Modal />
        ))}
    </>
  )
}

export default PinPage
