import { DiscountsApiResponseWithPath } from 'domain/model/discounts/main'
import { ReactNode, useCallback, useEffect, useMemo, useState } from 'react'
import {
  KEEP_SHOW_PIN,
  SELECTED_COMPANY_DISCOUNTS_PIN,
} from 'shared/storageNames'
import { selectedCompanyDiscountsController } from './controllers/selected-company-controller'
import { companyDiscountsController } from './controllers/company-discounts-controller'
import { SelectedCompanyDiscountsContext } from './context'

export interface GetCompanyDiscountsProps {
  storeUrl: string
  storeName: string
  shortname?: string
}

interface SelectedCompanyDiscountsProviderProps {
  children: ReactNode
}
function SelectedCompanyDiscountsProvider({
  children,
}: SelectedCompanyDiscountsProviderProps) {
  const [selectedCompanyDiscounts, setSelectedCompanyDiscounts] =
    useState<DiscountsApiResponseWithPath>()
  const [loading, setLoading] = useState(false)

  function setData(response: any) {
    sessionStorage.setItem(
      SELECTED_COMPANY_DISCOUNTS_PIN,
      JSON.stringify(response)
    )
    setSelectedCompanyDiscounts(response)
  }

  async function getCompanyDiscounts({
    storeUrl,
    storeName,
    shortname,
  }: GetCompanyDiscountsProps) {
    if (shortname) {
      setLoading(true)
      const selectedCompanyController = selectedCompanyDiscountsController()

      const cachedData = selectedCompanyController.getCachedData()

      if (
        selectedCompanyController.hasCache({
          cachedData,
          selectedCompanyShortname: shortname,
        })
      ) {
        setLoading(false)
        return setSelectedCompanyDiscounts(cachedData)
      }

      try {
        const companyController = companyDiscountsController()

        const chromeCachedData =
          await companyController.getCachedCompanyDiscountsData(shortname)

        if (companyController.notHaveCache(chromeCachedData)) {
          setLoading(false)
          return companyController.getDiscountsData({
            shortname,
            responseCallback: setData,
          })
        }

        sessionStorage.setItem(
          SELECTED_COMPANY_DISCOUNTS_PIN,
          JSON.stringify(chromeCachedData.data?.data)
        )
        setSelectedCompanyDiscounts(chromeCachedData.data?.data)
      } catch (e) {
        console.error(JSON.stringify(e))
        return setLoading(false)
      }
    }
    setLoading(false)
  }

  const hasCoupons = useCallback(() => {
    return !!selectedCompanyDiscounts?.discount_coupons.length
  }, [selectedCompanyDiscounts?.discount_coupons.length])

  const hasOffers = useCallback(() => {
    return !!selectedCompanyDiscounts?.discount_offers.length
  }, [selectedCompanyDiscounts?.discount_offers.length])

  const clearSelectedCompanyDiscounts = () => {
    sessionStorage.removeItem(SELECTED_COMPANY_DISCOUNTS_PIN)
    setSelectedCompanyDiscounts(undefined)
  }

  const couponsQuantity = useMemo(
    () => selectedCompanyDiscounts?.discount_coupons.length ?? 0,
    [selectedCompanyDiscounts]
  )
  const offersQuantity = useMemo(
    () => selectedCompanyDiscounts?.discount_offers.length ?? 0,
    [selectedCompanyDiscounts]
  )

  useEffect(() => {
    const sessionData = sessionStorage.getItem(SELECTED_COMPANY_DISCOUNTS_PIN)

    if (sessionData) {
      const parsedData = JSON.parse(sessionData)
      sessionStorage.setItem(KEEP_SHOW_PIN, 'true')
      return setSelectedCompanyDiscounts(parsedData)
    }
  }, [])

  return (
    <SelectedCompanyDiscountsContext.Provider
      value={{
        loading,
        selectedCompanyDiscounts,
        couponsQuantity,
        offersQuantity,
        couponsAndOffersQuantity: couponsQuantity + offersQuantity,
        hasOffers,
        hasCoupons,
        getCompanyDiscounts,
        clearSelectedCompanyDiscounts,
      }}
    >
      {children}
    </SelectedCompanyDiscountsContext.Provider>
  )
}

export default SelectedCompanyDiscountsProvider
