import { DiscountsApiResponseWithPath } from 'domain/model/discounts/main'
import { SELECTED_COMPANY_DISCOUNTS_PIN } from 'shared/storageNames'
import { isEmpty } from 'utils/isEmpty'

interface IsValidCacheDataProps {
  cachedData: DiscountsApiResponseWithPath
  selectedCompanyShortname?: string
}

export function selectedCompanyDiscountsController() {
  const getCachedData = () => {
    const sessionData = sessionStorage.getItem(SELECTED_COMPANY_DISCOUNTS_PIN)
    const parsedData: DiscountsApiResponseWithPath = sessionData
      ? JSON.parse(sessionData)
      : null

    return parsedData
  }

  const cachedDataIsValid = (data: DiscountsApiResponseWithPath) =>
    data && !isEmpty(data)

  const cachedCompanyShortnameIsSameSelectedCompanyShortname = ({
    cachedData,
    selectedCompanyShortname,
  }: IsValidCacheDataProps) =>
    cachedData?.company_info.short_name === selectedCompanyShortname

  const hasCache = ({
    cachedData,
    selectedCompanyShortname,
  }: IsValidCacheDataProps) =>
    cachedDataIsValid(cachedData) &&
    cachedCompanyShortnameIsSameSelectedCompanyShortname({
      cachedData,
      selectedCompanyShortname,
    })

  return {
    getCachedData,
    hasCache,
  }
}
