import { mdiChevronRight } from '@mdi/js'
import Icon from '@mdi/react'
import { EventAdapterTarget, eventAdapter } from 'adapter/event-adapter'
import { Card } from 'components/Card'
import EmptyResults from 'components/EmptyResults'
import Login from 'components/Login'
import MarketingBanner from 'components/MarketingBanner'
import { DiscountsCompanyInfo } from 'domain/model/discounts/discounts-company-info'
import {
  AreaLocation,
  ComponentLocation,
  EventOrigin,
} from 'domain/model/event'
import { IExtensionConfig } from 'hooks/Profile/state'
import useAuth from 'hooks/auth/use'
import React, { useCallback, useEffect, useState } from 'react'
import { useCompanyDiscounts } from 'scripts/pin-component/hooks/company-discounts'
import { useProfile } from 'scripts/pin-component/hooks/profile/use'
import { eventNamePrefix } from 'shared/gaEventsOrigin'
import { getCurrentUrl } from 'utils/location/get-current-url'
import { Notification as NotificationInterface } from '../../hooks/notifications/state'
import useNotifications from '../../hooks/notifications/use'
import { Logo } from './logo'
import * as S from './styles'

interface NotificationHomeProps {
  companyInfo?: DiscountsCompanyInfo | null
}
const NotificationHome: React.FC<NotificationHomeProps> = ({ companyInfo }) => {
  const { notifications, banners } = useNotifications()
  const { cachedProfile } = useProfile()
  const [showStatusReq, setShowStatusReq] = useState(true)

  const handleNotification = useCallback(() => {
    cachedProfile?.profile?.extension_config &&
      cachedProfile?.profile.extension_config.forEach(
        (pref: IExtensionConfig) => {
          if (
            pref.extension_id === '61ae7936dbf23f70d0e64d54' &&
            pref.isChecked === false
          ) {
            setShowStatusReq(false)
          }
        }
      )
  }, [cachedProfile])

  useEffect(() => {
    handleNotification()
  }, [handleNotification])

  const triggerEvent = useCallback(async () => {
    const active_url = await getCurrentUrl(EventOrigin.PIN)

    eventAdapter({
      target: EventAdapterTarget.current,
      data: {
        event: `${eventNamePrefix}complaint_response`,
        eventProps: {
          active_url,
          shortname: companyInfo?.short_name ?? '',
          company_name: companyInfo?.name ?? '',
          reputation: companyInfo?.general_reputation?.status ?? '',
          score: companyInfo?.general_reputation?.average_score ?? '',
          ra_verificada: companyInfo?.company_flags.is_verified ?? false,
          component: ComponentLocation.MODAL_PIN,
          area: AreaLocation.NOTIFICATION,
        },
      },
    })
  }, [
    companyInfo?.general_reputation?.average_score,
    companyInfo?.general_reputation?.status,
    companyInfo?.company_flags.is_verified,
    companyInfo?.name,
    companyInfo?.short_name,
  ])

  return (
    <div style={{ height: '100%' }}>
      <S.Title>Notificações</S.Title>
      {banners &&
        banners.map((banner) => (
          <MarketingBanner
            {...banner}
            companyInfo={companyInfo}
            eventObject={{
              eventOrigin: EventOrigin.PIN,
              componentLocation: ComponentLocation.MODAL_PIN,
              areaLocation: AreaLocation.NOTIFICATION,
            }}
          />
        ))}

      {notifications?.length > 0 ? (
        <S.CardList>
          {showStatusReq ? (
            notifications?.map((notification: NotificationInterface) => {
              return (
                <Card
                  backgroundColor='#fff'
                  padding='0px'
                  onClick={async () => {
                    await triggerEvent()
                    window.open(
                      `https://www.reclameaqui.com.br/minha-conta/responder-avaliar-reclamacao/${notification.id}/`,
                      '_blank'
                    )
                  }}
                  key={notification.id}
                >
                  <S.CardContainer>
                    <Logo />

                    {notification.status === 'ANSWERED' ? (
                      <S.TextContainer>
                        Sua reclamação da{' '}
                        <S.CompanyName>
                          {notification.companyName}
                        </S.CompanyName>{' '}
                        recebeu uma resposta
                      </S.TextContainer>
                    ) : (
                      <S.TextContainer>
                        {notification.title}{' '}
                        <S.CompanyName>
                          {notification.companyName}
                        </S.CompanyName>
                      </S.TextContainer>
                    )}

                    <S.Button>
                      <Icon path={mdiChevronRight} size='24px' />
                    </S.Button>
                  </S.CardContainer>
                </Card>
              )
            })
          ) : (
            <EmptyResults description='Você não tem novas notificações' />
          )}
        </S.CardList>
      ) : (
        <EmptyResults description='Você não tem novas notificações' />
      )}
    </div>
  )
}

const Notification: React.FC = () => {
  const { isAuthenticated } = useAuth()
  const { companyDiscounts } = useCompanyDiscounts()

  return (
    <S.Container isAuthenticated={isAuthenticated}>
      {isAuthenticated ? (
        <NotificationHome companyInfo={companyDiscounts?.company_info} />
      ) : (
        <Login
          companyInfo={companyDiscounts?.company_info}
          eventObject={{
            eventOrigin: EventOrigin.PIN,
            componentLocation: ComponentLocation.MODAL_PIN,
            areaLocation: AreaLocation.NOTIFICATION,
          }}
        />
      )}
    </S.Container>
  )
}

export default Notification
