const hiddenOffersList =  [
  "BAD",
  "NOT_RECOMMENDED",
  "UNDER_REVIEW",
  "SUSPENDED",
]

interface ICanShowOffersByReputation {
  status?: string;
  couponsSelectedStore?: boolean;
  campaignsSelectedStore?: boolean;
}

const canShowOffersByReputation = ({campaignsSelectedStore,couponsSelectedStore,status}: ICanShowOffersByReputation) => {
  if(campaignsSelectedStore || couponsSelectedStore)
    return true
  
  return status ? !hiddenOffersList.includes(status) : false
}

export default canShowOffersByReputation;