import AlertProvider from 'hooks/AlertProvider/provider'
import AuthProvider from 'hooks/auth/provider'
import { MemoryRouter, Route, Routes } from 'react-router-dom'
import { useModal } from 'scripts/pin-component/hooks/ModalProvider/use'
import Home from 'scripts/pin-component/pages/Home'
import Search from 'scripts/pin-component/pages/Search'
import User from 'scripts/pin-component/pages/User'
import Header from './Header'
import * as S from './styles'
import Notification from 'scripts/pin-component/pages/Notification'
import Footer from '../Footer'

const Modal = () => {
  const { closeModal } = useModal()

  return (
    <MemoryRouter initialEntries={['/home']}>
      <S.Main>
        <AlertProvider>
          <AuthProvider>
            <Header closeModal={closeModal} />
            <S.Content>
              <Routes>
                <Route path='home' element={<Home />} />
                <Route path='coupons' element={<Search />} />
                <Route path='notification' element={<Notification />} />
                <Route path='users' element={<User />} />
              </Routes>
            </S.Content>
            <Footer />
          </AuthProvider>
        </AlertProvider>
      </S.Main>
    </MemoryRouter>
  )
}

export default Modal
