import { makeRedirectUrl } from './redirectUrl'

export interface IComparatorSellerReputation {
  average_score: string
  status: string
}

interface IOpenRedirectPage {
  url: string
  code?: string
  seller: string
  sellerReputation: IComparatorSellerReputation
  sellerLogoUrl?: string
}

const openRedirectPage = ({
  url,
  code,
  seller,
  sellerReputation,
  sellerLogoUrl,
}: IOpenRedirectPage) => {
  return window.open(
    `${process.env.REACT_APP_REDIRECT_RA_URL}${makeRedirectUrl({
      url,
      code,
      seller,
      sellerLogoUrl: sellerLogoUrl || '',
      sellerReputation,
    })}`,
    '_blank',
    'noopener=true'
  )
}

export default openRedirectPage
