import { DiscountsApiResponseWithPath } from 'domain/model/discounts/main'
import { CONTENT_COMPANY_DISCOUNTS_CACHE_PREFIX } from 'shared/prefix-cache-names'
import { getContentScriptCurrentUrl } from 'utils/location/get-content-script-current-url'
import { tryJSONParse } from 'utils/try-json-parse'

export function companyDiscountsController() {
  const { shortSubdomainExtracted } = getContentScriptCurrentUrl()
  const cachePath =
    CONTENT_COMPANY_DISCOUNTS_CACHE_PREFIX + shortSubdomainExtracted

  function cacheData() {
    const cachedData = sessionStorage.getItem(cachePath)

    return {
      hasCache: !!cachedData,
      cachedData: tryJSONParse(cachedData ?? ''),
    }
  }

  function saveCache(data: DiscountsApiResponseWithPath) {
    sessionStorage.setItem(cachePath, JSON.stringify(data))
  }

  return { cacheData, saveCache }
}
