import WysiwygOutlinedIcon from '@mui/icons-material/WysiwygOutlined'
import { PinParamNames } from 'domain/services/profile/put-extension-pin-config'
import { ChangeEvent, useCallback, useMemo } from 'react'
import { useUpdatePinConfig } from 'scripts/pin-component/hooks/preferences/use-update-pin-config'
import { useProfile } from 'scripts/pin-component/hooks/profile/use'
import { subdomainRule, validUrl } from 'utils/urlRegex'
import BooleanOption from '../../PreferenceOptions/Boolean'
import ButtonOption from '../../PreferenceOptions/Button'
import ListOption from '../../PreferenceOptions/List'
import PreferencesLayout from '../Layout'
import {
  configKeysOrder,
  preferencesPinConfigList,
  silenceMinutesList,
} from './helper'

function PreferencesPin() {
  const { handleUpdatePinConfig } = useUpdatePinConfig()
  const { cachedProfile } = useProfile()

  const handleBooleanData = useCallback(
    (e: ChangeEvent<HTMLInputElement>) => {
      const {
        target: { name, checked },
      } = e

      handleUpdatePinConfig({
        paramName: name as PinParamNames,
        value: checked,
      })
    },
    [handleUpdatePinConfig]
  )

  const handleButtonData = useCallback(
    (name: string, value: number) => {
      handleUpdatePinConfig({
        paramName: name as PinParamNames,
        value,
      })
    },
    [handleUpdatePinConfig]
  )

  const handleListData = useCallback(
    (type: 'add' | 'remove', value: string) => {
      const name = 'blocked_domain_list'
      const currentList =
        cachedProfile?.profile?.extension_pin_config?.blocked_domain_list ?? []
      let newList: string[] = []

      if (type === 'add') newList = [...currentList, value]

      if (type === 'remove')
        newList = currentList?.filter((item) => item !== value)

      handleUpdatePinConfig({
        paramName: name,
        value: newList,
      })
    },
    [
      cachedProfile?.profile?.extension_pin_config?.blocked_domain_list,
      handleUpdatePinConfig,
    ]
  )

  const pinConfig = useMemo(
    () => cachedProfile?.profile?.extension_pin_config,
    [cachedProfile?.profile?.extension_pin_config]
  )

  return (
    <PreferencesLayout
      titleIcon={<WysiwygOutlinedIcon />}
      title='Janela flutuante'
      subtitle='Pop-ups que aparecem ao navegar nos sites'
    >
      {configKeysOrder.map(({ name, type }) => {
        const configValue = pinConfig?.[name as keyof typeof pinConfig]
        const { text, configId } = preferencesPinConfigList?.[name]

        if (type === 'number')
          return (
            <li>
              <ButtonOption
                key={name}
                title={text}
                buttonId={configId}
                currentValue={configValue ?? silenceMinutesList[0].value}
                list={silenceMinutesList}
                handleChange={(newValue) => handleButtonData(name, newValue)}
              />
            </li>
          )

        if (type === 'boolean')
          return (
            <li>
              <BooleanOption
                key={name}
                title={text}
                switchId={`${
                  !configValue ? 'ativou' : 'desativou'
                }_${configId}`}
                switchProps={{
                  name: name,
                  checked: (configValue as boolean) ?? false,
                  value: (configValue as boolean) ?? false,
                  onChange: handleBooleanData,
                }}
              />
            </li>
          )

        if (type === 'array')
          return (
            <li>
              <ListOption
                key={name}
                text={preferencesPinConfigList?.[name].text}
                list={(configValue as any[]) ?? []}
                validation={validUrl}
                dataExtractor={subdomainRule}
                handleChange={handleListData}
              />
            </li>
          )

        return null
      })}
    </PreferencesLayout>
  )
}

export default PreferencesPin
