import {
  DiscountsApiResponse,
  DiscountsApiResponseWithPath,
} from 'domain/model/discounts/main'
import {
  CacheHelperResponse,
  cacheHelper,
} from 'domain/services/fetch-company-discounts/helpers/cache'
import { COMPANY_DISCOUNTS_CACHE_PREFIX } from 'shared/prefix-cache-names'
import { isEmpty } from 'utils/isEmpty'

interface GetDiscountsDataProps {
  shortname: string
  responseCallback: (response: any) => void
}

export function companyDiscountsController() {
  const getCachedCompanyDiscountsData = async (shortname: string) =>
    await cacheHelper<DiscountsApiResponseWithPath | undefined>(
      COMPANY_DISCOUNTS_CACHE_PREFIX + shortname
    )

  const cachedDataIsInvalid = (
    data: DiscountsApiResponseWithPath | undefined
  ) => !data || isEmpty(data)

  const notHaveCache = (
    cachedData: CacheHelperResponse<DiscountsApiResponseWithPath | undefined>
  ) => cachedDataIsInvalid(cachedData.data?.data) || cachedData.isExpired

  const getDiscountsData = async ({
    shortname,
    responseCallback,
  }: GetDiscountsDataProps) => {
    chrome.runtime.sendMessage(
      { name: 'GET_COMPANY_DISCOUNTS', shortname },
      responseCallback
    )
  }
  const companyDiscountsIsInvalid = (data: DiscountsApiResponse) =>
    !data || isEmpty(data)

  return {
    notHaveCache,
    getDiscountsData,
    companyDiscountsIsInvalid,
    getCachedCompanyDiscountsData,
  }
}
