import { DiscountsApiResponseWithPath } from 'domain/model/discounts/main'
import { useChromeStorageLocalListener } from 'hooks/chromeStorageLocalListener'
import {
  ReactNode,
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from 'react'
import { CURRENT_COMPANY_DISCOUNTS } from 'shared/caches/company-discounts'
import { isSamePageOrigin } from 'utils/checkOrigin'
import { isEmpty } from 'utils/isEmpty'
import { companyDiscountsController } from './controller'

interface CompanyDiscountsContextProps {
  loading: boolean
  companyDiscounts?: DiscountsApiResponseWithPath | null
  couponsQuantity: number
  offersQuantity: number
  couponsAndOffersQuantity: number
}
const CompanyDiscountsContext = createContext<CompanyDiscountsContextProps>({
  loading: false,
  couponsQuantity: 0,
  offersQuantity: 0,
  couponsAndOffersQuantity: 0,
})

export const useCompanyDiscounts = () => useContext(CompanyDiscountsContext)

interface CompanyDiscountsProviderProps {
  children: ReactNode
}
function CompanyDiscountsProvider({ children }: CompanyDiscountsProviderProps) {
  const [companyDiscounts, setCompanyDiscounts] =
    useState<DiscountsApiResponseWithPath>()
  const [loading, setLoading] = useState(true)

  const { listenerData, currentData } =
    useChromeStorageLocalListener<DiscountsApiResponseWithPath>(
      CURRENT_COMPANY_DISCOUNTS
    )

  const getData = useCallback(async () => {
    const controller = companyDiscountsController()

    const cache = controller.cacheData()

    if (cache.hasCache) {
      setCompanyDiscounts(cache.cachedData)
      setLoading(false)
      return
    }

    const data = listenerData?.newValue ?? currentData

    if (data === undefined) return

    try {
      if (!data) throw new Error('Invalid data')

      const isSameOrigin = isSamePageOrigin(data?.path)

      if (!isSameOrigin) throw new Error('Is not same origin')

      if (isEmpty(data)) throw new Error('Empty data')

      controller.saveCache(data)
      setCompanyDiscounts(data)
      setLoading(false)
    } catch (e) {
      console.error(`PIN Company Discounts Provider: ${e}`)
      setCompanyDiscounts(undefined)
      setLoading(false)
    }
  }, [listenerData, currentData])

  useEffect(() => {
    getData()
  }, [getData])

  const couponsQuantity = useMemo(
    () => companyDiscounts?.discount_coupons.length ?? 0,
    [companyDiscounts]
  )
  const offersQuantity = useMemo(
    () => companyDiscounts?.discount_offers.length ?? 0,
    [companyDiscounts]
  )

  return (
    <CompanyDiscountsContext.Provider
      value={{
        companyDiscounts,
        loading,
        couponsQuantity,
        offersQuantity,
        couponsAndOffersQuantity: couponsQuantity + offersQuantity,
      }}
    >
      {children}
    </CompanyDiscountsContext.Provider>
  )
}

export default CompanyDiscountsProvider
