import { useEffect, useState } from 'react'
import { isString } from 'utils/cacheUtils'
import { isEmpty } from 'utils/isEmpty'
import { tryJSONParse } from 'utils/try-json-parse'

export const useChromeStorageLocalListener = <T,>(storageName: string) => {
  interface ListenerDataProps {
    newValue: T | undefined
    oldValue: T | undefined
  }
  const [listenerData, setListenerData] = useState<ListenerDataProps>()
  const [currentData, setCurrentData] = useState<T>()

  useEffect(() => {
    chrome.storage.onChanged.addListener((response) => {
      if (!response?.[storageName]) return

      const newValue = response?.[storageName].newValue
      const oldValue = response?.[storageName].oldValue

      const parsedNewValue = isString(newValue)
        ? tryJSONParse(newValue)
        : newValue
      const parsedOldValue = isString(oldValue)
        ? tryJSONParse(oldValue)
        : oldValue

      setCurrentData(parsedNewValue)

      setListenerData({
        newValue: parsedNewValue,
        oldValue: parsedOldValue,
      })
    })

    chrome.storage.local
      .get(storageName)
      .then((response) => {
        if (isEmpty(response)) return

        const data = response[storageName]
        setCurrentData(isString(data) ? tryJSONParse(data) : data)
      })
      .catch((e) => {
        console.error('Chrome storage local get error: ', e)
      })
  }, [storageName])

  return { listenerData, currentData }
}
