import HasDiscounts from 'components/HasDiscounts'
import Reputation from 'components/Reputation'
import CommonSurvey from 'components/Survey'
import {
  AreaLocation,
  ComponentLocation,
  EventOrigin,
} from 'domain/model/event'
import { Survey } from 'domain/model/survey'
import { getSurvey } from 'domain/services/survey'
import { useEffect, useMemo, useState } from 'react'
import CtaDiscountPage from 'scripts/pin-component/components/CtaDiscountPage'
import Discounts from 'scripts/pin-component/components/Discounts'
import { useCompanyDiscounts } from 'scripts/pin-component/hooks/company-discounts'
import { useProfile } from 'scripts/pin-component/hooks/profile/use'
import { isEmpty } from 'utils/isEmpty'
import * as S from './styles'

const Home = () => {
  const { companyDiscounts } = useCompanyDiscounts()
  const [survey, setSurvey] = useState<Survey>()
  const { cachedProfile } = useProfile()

  const companyInfo = useMemo(
    () => companyDiscounts?.company_info,
    [companyDiscounts?.company_info]
  )

  const storeIsValid = useMemo(() => !!companyInfo, [companyInfo])

  const storeIsNotEmpty = useMemo(() => !isEmpty(companyInfo), [companyInfo])

  const canShowStoreComponents = useMemo(
    () => storeIsValid && storeIsNotEmpty,
    [storeIsNotEmpty, storeIsValid]
  )

  const handleSurvey = async () => {
    try {
      const data = await getSurvey()
      setSurvey(data)
    } catch (_) {
      setSurvey(undefined)
    }
  }

  useEffect(() => {
    handleSurvey()
  }, [])

  const eventObject = {
    eventOrigin: EventOrigin.PIN,
    componentLocation: ComponentLocation.MODAL_PIN,
    areaLocation: AreaLocation.HOME,
  }

  return (
    <S.Main>
      {canShowStoreComponents && (
        <Reputation eventObject={eventObject} companyInfo={companyInfo!} />
      )}

      <S.Padding>
        {!!survey && survey.active && (
          <CommonSurvey
            data={survey}
            userId={cachedProfile?.profile?.user?.id}
          />
        )}

        <Discounts
          eventObject={eventObject}
          HasDiscounts={HasDiscounts}
          NoHasDiscounts={CtaDiscountPage}
        />
      </S.Padding>
    </S.Main>
  )
}

export default Home
