import {
  getTimeWithNow,
  PROFILE_EXTENSION_PIN_CONFIG_SILENCE_DURATION_DEFAULT,
} from 'shared/cache'
import { PIN_CONFIG_SILENCE_DURATION_CACHE_NAME } from 'shared/pinConfigCache'

export function addSilenceDurationCache(millies?: number) {
  localStorage.setItem(
    PIN_CONFIG_SILENCE_DURATION_CACHE_NAME,
    JSON.stringify(
      getTimeWithNow(
        millies ?? PROFILE_EXTENSION_PIN_CONFIG_SILENCE_DURATION_DEFAULT
      )
    )
  )
  window.dispatchEvent(new Event('storage'))
}
