import NotificationsOutlinedIcon from '@mui/icons-material/NotificationsOutlined'
import { Switch } from 'components/Switch'
import { ExtensionConfig } from 'pages/User/interface'
import {
  NotificationPreferencesDetails,
  NotificationPreferencesOrderList,
} from 'pages/User/mainPreferencesList'
import { useMemo } from 'react'
import { useUpdateConfig } from 'scripts/pin-component/hooks/preferences/use-update-config'
import { useUpdateNotificationsConfig } from 'scripts/pin-component/hooks/preferences/use-update-notifications-config'
import { useProfile } from 'scripts/pin-component/hooks/profile/use'
import { DefaultTheme, useTheme } from 'styled-components'
import { isEmpty } from 'utils/isEmpty'
import { isValidEmail } from 'utils/validEmail'
import StringOption from '../../PreferenceOptions/String'
import PreferencesLayout from '../Layout'
import * as S from './styles'

function PreferencesMain() {
  const { handleUpdateConfig } = useUpdateConfig()
  const { handleUpdateNotificationsConfig } = useUpdateNotificationsConfig()
  const { cachedProfile } = useProfile()
  const theme = useTheme()

  const renderConfig = (config?: ExtensionConfig) => {
    if (!config) return null

    const preferenceText = NotificationPreferencesDetails?.[config.extension_id]

    if (!preferenceText) return null

    return (
      <S.Main key={config.id}>
        <S.Title>{preferenceText.text}</S.Title>
        <Switch
          checked={config.isChecked}
          value={config.isChecked}
          onChange={() => handleUpdateConfig?.(config)}
        />
      </S.Main>
    )
  }

  const hasPreferentialEmail = useMemo(() => {
    if (!cachedProfile) return false

    return cachedProfile?.profile?.extension_notifications_config
      ?.preferential_email
      ? true
      : false
  }, [cachedProfile])

  const prefentialEmailValue = useMemo(() => {
    if (!cachedProfile) return ''

    return hasPreferentialEmail
      ? cachedProfile?.profile?.extension_notifications_config
          ?.preferential_email
      : cachedProfile?.profile?.user?.email
  }, [cachedProfile, hasPreferentialEmail])

  return (
    <>
      {cachedProfile?.profile &&
        !isEmpty(cachedProfile?.profile) &&
        preferenceGroups
          .map((event) => event(theme))
          .map(({ type, title, titleIcon, subtitle }) => (
            <PreferencesLayout
              titleIcon={titleIcon}
              title={title}
              subtitle={subtitle}
            >
              {NotificationPreferencesOrderList.map((configId) => {
                if (cachedProfile?.profile?.extension_config)
                  return cachedProfile?.profile?.extension_config?.find(
                    (config) => config.extension_id === configId
                  )

                return undefined
              }).map(renderConfig)}
              {type === 'NOTIFICATIONS' ? (
                <StringOption
                  title='Melhor e-mail para receber comunicações de descontos e ofertas'
                  value={prefentialEmailValue as string}
                  hasPreferentialEmail={hasPreferentialEmail}
                  validation={isValidEmail}
                  handleChange={(value) =>
                    handleUpdateNotificationsConfig({
                      paramName: 'preferential_email',
                      value,
                    })
                  }
                />
              ) : null}
            </PreferencesLayout>
          ))}
    </>
  )
}

export default PreferencesMain

const preferenceGroups = [
  (theme: DefaultTheme) => ({
    type: 'NOTIFICATIONS',
    title: 'Receber comunicações',
    titleIcon: <NotificationsOutlinedIcon />,
    subtitle:
      'Informações que aparecem na sessão de  notificações da extensão.',
  }),
]
