import { EventAdapterTarget, eventAdapter } from 'adapter/event-adapter'
import { DiscountsCompanyInfo } from 'domain/model/discounts/discounts-company-info'
import { EventObject, EventOrigin } from 'domain/model/event'
import useAuth from 'hooks/auth/use'
import { removeChromeLocalData } from 'hooks/chrome-storage-change-data'
import { useCallback } from 'react'
import { EXTENSION_TOUR_CACHE_NAME } from 'scripts/extension-tour/helper'
import { eventNamePrefix } from 'shared/gaEventsOrigin'
import { getCurrentUrl } from 'utils/location/get-current-url'
import * as S from './styles'

interface SuccessLoginProps {
  companyInfo?: DiscountsCompanyInfo | null
  eventObject: EventObject
}
const SuccessLogin = ({ companyInfo, eventObject }: SuccessLoginProps) => {
  const { setFirstLogin } = useAuth()

  const eventTrigger = useCallback(
    async (event: string) => {
      const active_url = await getCurrentUrl(eventObject.eventOrigin)

      eventAdapter({
        target: EventAdapterTarget.current,
        data: {
          event: `${eventNamePrefix}${event}`,
          eventProps: {
            active_url,
            shortname: companyInfo?.short_name ?? '',
            company_name: companyInfo?.name ?? '',
            reputation: companyInfo?.general_reputation?.status ?? '',
            score: companyInfo?.general_reputation?.average_score ?? '',
            ra_verificada: companyInfo?.company_flags.is_verified ?? false,
            component: eventObject.componentLocation,
            area: eventObject.areaLocation,
          },
        },
      })
    },
    [
      eventObject,
      companyInfo?.general_reputation?.average_score,
      companyInfo?.general_reputation?.status,
      companyInfo?.company_flags.is_verified,
      companyInfo?.name,
      companyInfo?.short_name,
    ]
  )

  return (
    <S.Main>
      <S.Image
        alt='Success login happy ervilho'
        src={`${process.env.REACT_APP_ASSETS_IMAGES_BUCKET_URL}/ra_cupons/extension/common/success_login/happy-ervilho.svg`}
      />
      <S.Title> Login efetuado com sucesso! </S.Title>
      <S.Paragraph>
        Saiba como usar o assistente de compra do Reclame AQUI e aproveite todas
        as vantagens , clique em <strong>Fazer Tour</strong>!
      </S.Paragraph>
      <div>
        <S.Button
          margin='40px 0px 0px 0px'
          background='#02793E'
          color='white'
          target='_blank'
          id={
            eventObject.eventOrigin === EventOrigin.EXTENSION
              ? 'tour_button_sucess_login'
              : 'pin_tour_button_sucess_login'
          }
          onClick={async () => {
            setFirstLogin(false)
            await eventTrigger('tour')
            await removeChromeLocalData(EXTENSION_TOUR_CACHE_NAME)
          }}
          href={`${process.env.REACT_APP_REDIRECT_RA_URL}/extensao/`}
        >
          Fazer tour
        </S.Button>
        <S.Button
          margin='24px 0px 0px 0px'
          background='white'
          color='#4B5963'
          border='1px solid #E1E3E5'
          target='_blank'
          id={
            eventObject.eventOrigin === EventOrigin.EXTENSION
              ? 'pass_tour_button_sucess_login'
              : 'pass_pin_tour_button_sucess_login'
          }
          onClick={async () => {
            setFirstLogin(false)
            await eventTrigger('skip_tour')
          }}
        >
          Pular o tour
        </S.Button>
      </div>
    </S.Main>
  )
}

export default SuccessLogin
