import { NotificationsParamNames } from 'domain/services/profile/put-extension-notifications-config'
import { useAlert } from 'hooks/AlertProvider/use'
import useAuth from 'hooks/auth/use'
import { useCallback } from 'react'
import { preferenceTypes } from 'scripts/long-live-message/listener-rules/preferences/preferences-listener'
import { useProfile } from '../profile/use'

let currentPort

interface HandleUpdateProps {
  paramName: NotificationsParamNames
  value: string
}
export function useUpdateNotificationsConfig() {
  const { token } = useAuth()
  const { openAlert } = useAlert()
  const { cachedProfile, setProfile } = useProfile()

  const handleUpdateNotificationsConfig = useCallback(
    ({ paramName, value }: HandleUpdateProps) => {
      if (cachedProfile?.profile) {
        currentPort = chrome.runtime.connect({ name: 'PREFERENCES' })
        currentPort.postMessage({
          type: preferenceTypes.updateNotificationsConfig,
          data: {
            token,
            paramName,
            value,
          },
        })
        currentPort.onMessage.addListener((data) => {
          if (data.status < 200 || data.status > 299)
            return openAlert?.({
              title: 'Erro',
              message: data.message,
              severity: 'error',
            })

          openAlert?.({
            title: 'Sucesso',
            message: 'Informação salva com sucesso.',
            severity: 'success',
          })
          setProfile?.({
            ...cachedProfile,
            profile: {
              ...cachedProfile.profile,
              extension_notifications_config: {
                ...cachedProfile.profile.extension_notifications_config!,
                [paramName]: value,
              },
            },
          })
        })
        currentPort.onDisconnect.addListener(() => {
          currentPort = null
        })
      }
    },
    [cachedProfile, openAlert, setProfile, token]
  )

  return { handleUpdateNotificationsConfig }
}
