import {
  mixpanelIdentifyLogin,
  mixpanelIdentifyLogout,
} from 'adapter/event-adapter/mixpanel-identify'
import useAuth from 'hooks/auth/use'
import {
  getChromeLocalData,
  removeChromeLocalData,
  setChromeLocalData,
  setChromeSyncData,
} from 'hooks/chrome-storage-change-data'
import { ReactNode, useEffect } from 'react'
import { IS_IDENTIFIED_PIN, REMOVE_IDENTIFY_PIN } from 'shared/caches/event'
import { ProfileContext } from './context'
import { CachedProfile } from './state'
import { useSyncProfile } from './use'

let currentPort
interface ProfileProviderProps {
  children: ReactNode
}
export function ProfileProvider({ children }: ProfileProviderProps) {
  const { currentData: cachedProfile } = useSyncProfile()
  const { isAuthenticated, token } = useAuth()

  const setProfile = async (data: CachedProfile) => {
    await setChromeSyncData({ profile: data })
  }

  const getProfile = async () => {
    if (!isAuthenticated) return

    currentPort = chrome.runtime.connect({ name: 'PROFILE' })
    currentPort.postMessage({ type: 'GET' })
    currentPort.onDisconnect.addListener(() => {
      currentPort = null
    })
  }

  useEffect(() => {
    async function identifyFunc() {
      const isIdentifiedData = await getChromeLocalData(IS_IDENTIFIED_PIN)
      const removeIdentifyData = await getChromeLocalData(REMOVE_IDENTIFY_PIN)

      const isIdentified = isIdentifiedData?.[IS_IDENTIFIED_PIN]
      const removeIdentify = removeIdentifyData?.[REMOVE_IDENTIFY_PIN]
      const hasProfile = cachedProfile?.profile.user

      if (removeIdentify) {
        await setChromeLocalData({
          [REMOVE_IDENTIFY_PIN]: false,
        })
        await removeChromeLocalData('clientId')
        return mixpanelIdentifyLogout()
      }

      if (!isIdentified && hasProfile) {
        await setChromeLocalData({
          [IS_IDENTIFIED_PIN]: true,
          clientId: cachedProfile?.profile.user.userId,
        })
        mixpanelIdentifyLogin(cachedProfile?.profile.user.userId)
      }
    }
    identifyFunc()
  }, [cachedProfile])

  useEffect(() => {
    if (token) getProfile()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [token])

  return (
    <ProfileContext.Provider
      value={{
        cachedProfile,
        setProfile,
      }}
    >
      {children}
    </ProfileContext.Provider>
  )
}
