import CloseIcon from '@mui/icons-material/Close'
import Button from 'components/Button'
import { SmallTextField } from 'components/TextField'
import { useTheme } from 'styled-components'
import * as S from './styles'

interface DialogProps {
  list?: any[]
  inputValue: string
  inputLabel: string
  openList?: boolean
  openAdd?: boolean
  canSave: boolean
  dialogTitle: string
  addValue: () => void
  inputValueIsValid?: (value: any) => boolean
  dialogClose: () => void
  setCanSave: (value: boolean) => void
  handleChange?: (type: 'add' | 'remove', value: string) => void
  setInputValue: (value: string) => void
}
export function Dialog({
  list,
  inputValue,
  inputLabel,
  openList = false,
  openAdd = false,
  canSave,
  dialogTitle,
  addValue,
  inputValueIsValid,
  dialogClose,
  setCanSave,
  handleChange,
  setInputValue,
}: DialogProps) {
  const theme = useTheme()

  return (
    <S.Main onClick={dialogClose} open={openList || openAdd}>
      <S.Dialog
        onClick={(e) => {
          e.preventDefault()
          e.stopPropagation()
        }}
      >
        <S.DialogContent>
          {openList ? (
            <S.DialogContentTextList>{dialogTitle}</S.DialogContentTextList>
          ) : (
            <S.DialogContentTextAddSite>
              {dialogTitle}
            </S.DialogContentTextAddSite>
          )}
          {openAdd ? (
            <SmallTextField
              label={inputLabel}
              value={inputValue}
              onChange={(e) => {
                const {
                  target: { value },
                } = e

                if (!inputValueIsValid?.(value)) setCanSave(false)
                else setCanSave(true)

                setInputValue(value)
              }}
            />
          ) : null}
          {openList ? (
            <S.SitesList>
              {list?.map((item) => (
                <S.SiteItem key={item}>
                  <p>{item}</p>
                  <S.IconButton
                    aria-label='remove-site'
                    onClick={() => {
                      handleChange?.('remove', item)
                    }}
                  >
                    <CloseIcon />
                  </S.IconButton>
                </S.SiteItem>
              ))}
            </S.SitesList>
          ) : null}
        </S.DialogContent>
        <S.DialogActions openList={openList}>
          {openAdd ? (
            <Button
              color='#fff'
              bgColor={!canSave ? theme.colors.metal : theme.colors.pickles}
              hoverColor='#fff'
              hoverBgColor={
                canSave && openAdd
                  ? theme.colors.secondaryGreen
                  : theme.colors.metal
              }
              width='100%'
              onClick={addValue}
              disabled={!canSave}
            >
              Salvar
            </Button>
          ) : null}
          <Button
            color={openList ? '#fff' : theme.colors.steel}
            bgColor={openList ? theme.colors.pickles : theme.colors.iron}
            hoverColor={openList ? '#fff' : theme.colors.steel}
            hoverBgColor={
              openList ? theme.colors.secondaryGreen : theme.colors.metal
            }
            width={openList ? '83px' : '100%'}
            onClick={dialogClose}
          >
            {openAdd ? 'Cancelar' : null}
            {openList ? 'Fechar' : null}
          </Button>
        </S.DialogActions>
      </S.Dialog>
    </S.Main>
  )
}
