import SearchBox from 'components/SearchBoxPin'
import StoreCoupon from 'components/StoreCoupon'
import {
  AreaLocation,
  ComponentLocation,
  EventOrigin,
} from 'domain/model/event'
import { useEffect, useState, useTransition } from 'react'
import { useDiscountsSummary } from 'scripts/pin-component/hooks/discounts-summary-provider/use'
import { useSelectedCompanyDiscounts } from 'scripts/pin-component/hooks/selected-company-discounts/use'
import { INoCoupons } from 'shared/types/search-page'
import SkeletonNoCoupons from '../SkeletonNoCoupons'
import * as S from './styles'

const NoCoupons = ({
  loading,
  filteredDiscountsSummary,
  searchHandle,
}: INoCoupons) => {
  const [searchTerm, setSearchTerm] = useState<string>('')
  const [debouncedSearchTerm, setDebouncedSearchTerm] = useState<string>('')
  const [, startTransition] = useTransition()
  const { discountsSummary } = useDiscountsSummary()
  const { getCompanyDiscounts } = useSelectedCompanyDiscounts()

  useEffect(() => {
    startTransition(() => {
      setDebouncedSearchTerm(searchTerm)
    })
  }, [searchTerm])

  useEffect(() => {
    searchHandle(debouncedSearchTerm)
  }, [debouncedSearchTerm, searchHandle])

  return loading || !discountsSummary ? (
    <SkeletonNoCoupons width='250px' height='140px' />
  ) : (
    <S.StoresContainer>
      <SearchBox setSearchTerm={setSearchTerm} />
      {searchTerm.length > 0 && (
        <>
          <S.TitleSearch>Resultados para: {searchTerm}</S.TitleSearch>
          {filteredDiscountsSummary.length <= 0 && searchTerm.length > 0 ? (
            <>
              <S.NumberOfStoresFinded>
                Não conseguimos buscar o termo pesquisado! Conheça outras lojas
                que possuem cupons disponíveis.
              </S.NumberOfStoresFinded>
              <S.StoreCouponsCardsContainer id='scroller'>
                {discountsSummary && discountsSummary.length > 0 ? (
                  discountsSummary.map((discount) => (
                    <StoreCoupon
                      key={discount.company_info.id}
                      discount={discount}
                      searchTerm={searchTerm}
                      eventObject={{
                        eventOrigin: EventOrigin.PIN,
                        componentLocation: ComponentLocation.MODAL_PIN,
                        areaLocation: AreaLocation.SEARCH,
                      }}
                      handleStoreData={() => {
                        getCompanyDiscounts?.({
                          storeName: discount.company_info.name,
                          storeUrl: discount.company_info.url,
                          shortname: discount.company_info.short_name,
                        })
                      }}
                    />
                  ))
                ) : (
                  <SkeletonNoCoupons width='118px' height='140px' />
                )}
              </S.StoreCouponsCardsContainer>
            </>
          ) : (
            <S.NumberOfStoresFinded>
              {filteredDiscountsSummary.length} lojas encontradas
            </S.NumberOfStoresFinded>
          )}
        </>
      )}
      <S.StoreCouponsCardsContainer id='scroller'>
        {filteredDiscountsSummary && filteredDiscountsSummary.length > 0 ? (
          filteredDiscountsSummary.map((discount) => (
            <StoreCoupon
              key={discount.company_info.id}
              discount={discount}
              searchTerm={searchTerm}
              eventObject={{
                eventOrigin: EventOrigin.PIN,
                componentLocation: ComponentLocation.MODAL_PIN,
                areaLocation: AreaLocation.SEARCH,
              }}
              handleStoreData={() => {
                getCompanyDiscounts?.({
                  storeName: discount.company_info.name,
                  storeUrl: discount.company_info.url,
                  shortname: discount.company_info.short_name,
                })
              }}
            />
          ))
        ) : (
          <SkeletonNoCoupons width='118px' height='140px' />
        )}
      </S.StoreCouponsCardsContainer>
    </S.StoresContainer>
  )
}

export default NoCoupons
