import { EventAdapterTarget, eventAdapter } from 'adapter/event-adapter'
import { ComponentLocation } from 'domain/model/event'
import { useSyncProfile } from 'hooks/Profile/use'
import { useCallback } from 'react'
import { addSilenceDurationCache } from 'scripts/pin-component/helpers/silenceDurationCache'
import { useCompanyDiscounts } from 'scripts/pin-component/hooks/company-discounts'
import { useModal } from 'scripts/pin-component/hooks/ModalProvider/use'
import { PinState } from 'scripts/pin-component/models/pinState'
import { eventNamePrefix } from 'shared/gaEventsOrigin'
import { isEmpty } from 'utils/isEmpty'
import { convertMinutesToMillies } from 'utils/timeHelper'
import * as S from './styles'

interface ClosePinGAEventProps {
  setPinState: React.Dispatch<React.SetStateAction<PinState | undefined>>
}
function ClosePinGAEvent({ setPinState }: ClosePinGAEventProps) {
  const {
    companyDiscounts,
    couponsQuantity,
    offersQuantity,
    couponsAndOffersQuantity,
  } = useCompanyDiscounts()
  const { closeModal } = useModal()
  const { currentData: cachedProfile } = useSyncProfile()

  const clearPinState = useCallback(() => {
    setPinState(undefined)
  }, [setPinState])

  const closePin = useCallback(() => {
    if (cachedProfile?.profile && !isEmpty(cachedProfile?.profile)) {
      addSilenceDurationCache(
        cachedProfile?.profile?.extension_pin_config?.silence_duration_minutes
          ? convertMinutesToMillies(
              cachedProfile?.profile?.extension_pin_config
                .silence_duration_minutes
            )
          : undefined
      )
    } else addSilenceDurationCache()

    clearPinState()
  }, [cachedProfile?.profile, clearPinState])

  const closePinEvent: React.MouseEventHandler<HTMLButtonElement> = (event) => {
    event.stopPropagation()
    event.preventDefault()

    eventAdapter({
      target: EventAdapterTarget.current,
      data: {
        event: `${eventNamePrefix}close_pin`,
        eventProps: {
          active_url: window.location.href,
          shortname: companyDiscounts?.company_info?.short_name,
          company_name: companyDiscounts?.company_info?.name,
          reputation: companyDiscounts?.company_info?.general_reputation.status,
          score:
            companyDiscounts?.company_info.general_reputation?.average_score,
          ra_verificada: companyDiscounts?.company_info.company_flags
            ?.is_verified
            ? true
            : false,
          total_discounts: couponsAndOffersQuantity,
          coupons: couponsQuantity,
          offers: offersQuantity,
          component: ComponentLocation.PIN,
        },
      },
    })

    closePin()
    closeModal?.()
  }

  return <S.Container onClick={closePinEvent} />
}

export default ClosePinGAEvent
