import { PinState } from 'scripts/pin-component/models/pinState'
import styled, { keyframes } from 'styled-components'

export const Icon = styled.div`
  height: 14px;
  width: 14px;
  overflow: hidden;
`

interface IState {
  state: PinState
}

const showPin = keyframes`
  0% { right: -214px; }
  100% { right: 20px; }
`

const glowing = keyframes`
  0% { box-shadow: 0px 4px 44px #F09704 }
  100% { box-shadow: 0px 4px 46px #B67C1D }
`

export const CloseButton = styled.button`
  background-color: #fff;
  border: none;
  border-radius: 100px;
  box-shadow: 1px 1px 2px rgba(0, 0, 0, 0.25);
  cursor: pointer;
  padding: 0;
  width: 16px;
  height: 16px;
  transition: 1s;

  display: none;
  align-items: center;
  justify-content: center;

  position: absolute;
  top: 0;
  right: 0;
`

export const WarningIcon = styled.aside`
  background-color: ${({ theme }) => theme.colors.pan_light};
  box-shadow: 1px 1px 4px rgba(0, 0, 0, 0.25);
  border-radius: 100px;
  color: #fff;
  width: 24px;
  height: 24px;
  max-width: 24px;
  max-height: 24px;

  transition: all 1.5s linear;

  display: flex;
  align-items: center;
  justify-content: center;

  position: absolute;
  bottom: -6px;
  right: -6px;

  & > p {
    font-weight: 600;
    font-size: 14px;
    padding: 0;
    margin: 0;
  }

  ${Icon} {
    width: 0px;
  }
`

export const Title = styled.h2<IState>`
  font-weight: 700;
  font-size: 12px;
  line-height: 16px;
  text-align: center;
  max-width: 146px;
  color: #ffffff;

  display: ${({ state }) =>
    state === PinState.FirstStart ? 'inline' : 'none'};
  transition: 1s;
`

export const Logo = styled.div`
  min-width: 30px;
  min-height: 30px;
  max-width: 30px;
  max-height: 30px;
`

export interface ITag {
  width?: string
  backgroundcolor: string
  fontColor: string
}

export const Tag = styled.div<ITag>`
  display: flex;
  flex-direction: row;
  justify-content: center;
  align-items: center;
  border-radius: 32px;
  padding: 0px 5px;
  font-size: 12px;
  line-height: 16px;
  font-weight: 700;
  color: ${({ fontColor }) => (fontColor ? fontColor : 'black')};
  width: ${({ width }) => (width ? width : 'auto')};
  height: 0px;
  background-color: ${({ backgroundcolor }) =>
    backgroundcolor ? backgroundcolor : ''};
  overflow: hidden;
`

const GaEventElement = styled.aside`
  position: absolute;
`
export const PinGAEvent = styled(GaEventElement)<IState>`
  inset: 0;
  min-width: ${({ state }) =>
    state === PinState.FirstStart ? '214px' : '60px'};
  max-width: ${({ state }) =>
    state === PinState.FirstStart ? '214px' : '60px'};
  max-height: 44px;
  border-top-left-radius: ${({ state }) =>
    state === PinState.FirstStart ? '25px' : '100px'};
  border-top-right-radius: ${({ state }) =>
    state === PinState.FirstStart ? '25px' : '100px'};
  z-index: 1;
  transition: min-width 1s, max-width 1s, border-radius 1s;
`

const StartHidedGaEventElement = styled(GaEventElement)`
  display: none;
`

export const ClosePinGAEvent = styled(StartHidedGaEventElement)`
  inset: 0 0 auto auto;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  z-index: 2;
`

export const Main = styled.section<IState>`
  background: linear-gradient(180deg, #f09704 0%, #b67c1d 100%);
  border-radius: 100px;
  cursor: pointer;
  min-width: ${({ state }) =>
    state === PinState.FirstStart ? '214px' : '60px'};
  max-width: ${({ state }) =>
    state === PinState.FirstStart ? '214px' : '60px'};
  min-height: 60px;
  max-height: 60px;
  transition: min-width 1s, max-width 1s, min-height 1s, max-height 1s,
    height 1s, justify-content 1s;
  animation-name: ${showPin};
  animation-duration: 1s;
  animation-iteration-count: 1;
  display: flex;
  flex-direction: ${({ state }) =>
    state === PinState.FirstStart ? 'row' : 'column'};
  align-items: center;
  justify-content: ${({ state }) =>
    state === PinState.FirstStart ? 'space-evenly' : 'center'};
  position: fixed;
  top: 50%;
  right: 20px;
  z-index: 999999999999;

  &::before {
    content: '';
    border-radius: 100px;
    min-width: ${({ state }) =>
      state === PinState.FirstStart ? '214px' : '60px'};
    max-width: ${({ state }) =>
      state === PinState.FirstStart ? '214px' : '60px'};
    min-height: 60px;
    max-height: 60px;
    transition: min-width 1s, max-width 1s, min-height 1s, max-height 1s,
      height 1s, padding-top 1s, justify-content 1s;
    animation-name: ${({ state }) =>
      state === PinState.FirstStart ? '' : glowing};
    animation-duration: 5s;
    animation-delay: 0.8s;
    animation-iteration-count: 4;
    position: fixed;
    z-index: -1;
    top: 50%;
    right: 20px;
  }

  ${({ state }) =>
    state !== PinState.FirstStart
      ? `
    &:hover ${CloseButton} {
      display: flex;
    }

    &:hover ${StartHidedGaEventElement} {
      display: block;
    }
  `
      : ''}
`
