import { Affiliate } from 'shared/affiliates';

interface AffiliatePrefixData {
  affiliates: Affiliate[];
  affiliateId: number;
}
export class AffiliatePrefix {
  private affiliates: Affiliate[];

  private affiliateId: number;

  constructor({ affiliates, affiliateId }: AffiliatePrefixData) {
    this.affiliates = affiliates;
    this.affiliateId = affiliateId;
  }

  get() {
    if (!this.affiliateId) return undefined;

    return this.affiliates.find(affiliate => affiliate.id === this.affiliateId)
      ?.prefix;
  }
}
