import { ReactNode } from 'react'
import { Container as PageContainer } from './styles'

export interface PageContainerProps {
  minHeight?: string
  maxHeight?: string
  gap?: string
  padding?: string
  children: ReactNode
}

const Container = ({
  children,
  minHeight,
  maxHeight,
  gap = '16px',
  padding,
}: PageContainerProps) => {
  return (
    <PageContainer
      gap={gap}
      minHeight={minHeight}
      maxHeight={maxHeight}
      padding={padding}
    >
      {children}
    </PageContainer>
  )
}

export default Container
