import { useEffect, useState } from 'react'
import {
  CheckIfTabIsPopupResponse,
  TABS_TYPES,
} from 'scripts/long-live-message/listener-rules/tabs-listener'
import { getContentScriptCurrentUrl } from 'utils/location/get-content-script-current-url'

let currentPort

export const useWindowIsPopup = () => {
  const [windowIsPopup, setWindowIsPopup] = useState<boolean>()

  useEffect(() => {
    async function checkIfIsPopup() {
      const { shortSubdomainExtracted } = getContentScriptCurrentUrl()
      currentPort = chrome.runtime.connect({ name: 'TABS' })
      currentPort.postMessage({
        type: TABS_TYPES.CHECK_IF_TAB_IS_POPUP,
        data: { domain: shortSubdomainExtracted },
      })
      currentPort.onMessage.addListener((data: CheckIfTabIsPopupResponse) => {
        setWindowIsPopup(data.isPopup)
      })
      currentPort.onDisconnect.addListener(() => {
        currentPort = null
      })
    }
    checkIfIsPopup()
  }, [])

  return { windowIsPopup }
}
