import { PinParamNames } from 'domain/services/profile/put-extension-pin-config'
import { AlertProps } from 'hooks/AlertProvider/state'
import { useAlert } from 'hooks/AlertProvider/use'
import useAuth from 'hooks/auth/use'
import { silenceMinutesList } from 'pages/User/components/Preferences/Pin/helper'
import { useCallback } from 'react'
import { preferenceTypes } from 'scripts/long-live-message/listener-rules/preferences/preferences-listener'
import { useProfile } from '../profile/use'

function getTimeText(value: number) {
  return silenceMinutesList.find((item) => item.value === value)?.text
}

interface UpdateProfile {
  paramName: PinParamNames
  value: number | boolean | string[]
}
const updatePinAlert = ({ paramName, value }: UpdateProfile): AlertProps => {
  if (paramName === 'silence_duration_minutes')
    return {
      title: 'Sucesso',
      message: `Ao fechar o pin flutuante ele não aparecerá por ${getTimeText(
        value as number
      )}`,
      severity: 'success',
    }

  return {
    title: 'Sucesso',
    message: value
      ? 'Informação salva com sucesso!'
      : 'Desabilitado com sucesso!',
    severity: 'success',
  }
}

let currentPort

export function useUpdatePinConfig() {
  const { cachedProfile, setProfile } = useProfile()
  const { token } = useAuth()
  const { openAlert } = useAlert()

  const handleUpdatePinConfig = useCallback(
    ({ paramName, value }: UpdateProfile) => {
      if (cachedProfile?.profile) {
        currentPort = chrome.runtime.connect({ name: 'PREFERENCES' })
        currentPort.postMessage({
          type: preferenceTypes.updatePinConfig,
          data: {
            token,
            paramName,
            value,
          },
        })
        currentPort.onMessage.addListener((data) => {
          if (data.status < 200 || data.status > 299)
            return openAlert?.({
              title: 'Erro',
              message: data.message,
              severity: 'error',
            })

          openAlert?.(updatePinAlert({ paramName, value }))

          setProfile?.({
            ...cachedProfile,
            profile: {
              ...cachedProfile.profile,
              extension_pin_config: {
                ...cachedProfile?.profile?.extension_pin_config,
                [paramName]: value,
              },
            },
          })
        })
        currentPort.onDisconnect.addListener(() => {
          currentPort = null
        })
      }
    },
    [cachedProfile, openAlert, setProfile, token]
  )

  return { handleUpdatePinConfig }
}
