import ErrorIcon from '@mui/icons-material/Error'
import { useUpdatePinConfig } from 'scripts/pin-component/hooks/preferences/use-update-pin-config'
import { useTheme } from 'styled-components'
import * as S from './styles'

function PinDisabledWarning() {
  const theme = useTheme()
  const { handleUpdatePinConfig } = useUpdatePinConfig()

  return (
    <S.Main>
      <ErrorIcon sx={S.IconSx(theme)} />
      <S.Text>
        A janela flutuante está desativado para todos os sites.{' '}
        <S.Button
          role='button'
          onClick={() => {
            handleUpdatePinConfig({
              paramName: 'disable_pin',
              value: false,
            })
          }}
        >
          Clique AQUI para ativar
        </S.Button>
      </S.Text>
    </S.Main>
  )
}

export default PinDisabledWarning
