import { mdiPlusCircle } from '@mdi/js'
import Icon from '@mdi/react'
import { EventAdapterTarget, eventAdapter } from 'adapter/event-adapter'
import Report from 'components/Report'
import ReputationScore from 'components/ReputationScore'
import Text from 'components/Text'
import VerifyTag from 'components/VerifyTag'
import { DiscountsCompanyInfo } from 'domain/model/discounts/discounts-company-info'
import {
  AreaLocation,
  ComponentLocation,
  EventOrigin,
} from 'domain/model/event'
import { useRavConfig } from 'hooks/rav-config/use-rav-config'
import { useCallback, useEffect, useMemo, useState } from 'react'
import { eventNamePrefix } from 'shared/gaEventsOrigin'
import { light } from 'styles/themes/basic'
import { getPhrase } from 'utils/getPhrase'
import { isEmpty } from 'utils/isEmpty'
import { getCurrentUrl } from 'utils/location/get-current-url'
import ReputationModalSkeleton from './Skeleton'
import * as S from './styles'

const noIndexList = ['NO_INDEX', 'NO_INDEX_VERIFIED']

export interface ReputationEventObject {
  eventOrigin: EventOrigin
  componentLocation: ComponentLocation
  areaLocation: AreaLocation
}

interface IReputation {
  companyInfo: DiscountsCompanyInfo
  eventObject: ReputationEventObject
}
const Reputation = ({ companyInfo, eventObject }: IReputation) => {
  const [expanded, setExpanded] = useState(false)

  const reputation = useMemo(
    () => companyInfo && getPhrase(companyInfo?.general_reputation?.status),
    [companyInfo]
  )

  const changeExpand = useCallback(async () => {
    if (!expanded) {
      const active_url = await getCurrentUrl(eventObject.eventOrigin)

      eventAdapter({
        target: EventAdapterTarget.current,
        data: {
          event: `${eventNamePrefix}open_reputation_details`,
          eventProps: {
            active_url,
            shortname: companyInfo?.short_name ?? '',
            company_name: companyInfo?.name ?? '',
            reputation: companyInfo?.general_reputation?.status ?? '',
            score: companyInfo?.general_reputation?.average_score ?? '',
            ra_verificada: companyInfo?.company_flags.is_verified ?? false,
            component: eventObject.componentLocation,
            area: eventObject.areaLocation,
          },
        },
      })
    }
    setExpanded(!expanded)
  }, [expanded, setExpanded, companyInfo, eventObject])

  const handleNoIndexButVerify = useMemo(() => {
    return (
      noIndexList.includes(companyInfo?.general_reputation?.status) &&
      companyInfo.company_flags.is_verified
    )
  }, [
    companyInfo.company_flags.is_verified,
    companyInfo?.general_reputation?.status,
  ])

  const ravConfig = useRavConfig()

  useEffect(() => {
    ravConfig.get(companyInfo?.general_reputation?.status ?? 'NO_INDEX')
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const textNoIndexButVerify = useMemo(
    () => ravConfig.data?.text,
    [ravConfig.data]
  )

  const understandReputation = useCallback(async () => {
    const active_url = await getCurrentUrl(eventObject.eventOrigin)

    eventAdapter({
      target: EventAdapterTarget.current,
      data: {
        event: `${eventNamePrefix}understand_reputation`,
        eventProps: {
          active_url,
          shortname: companyInfo?.short_name ?? '',
          company_name: companyInfo?.name ?? '',
          reputation: companyInfo?.general_reputation?.status ?? '',
          score: companyInfo?.general_reputation?.average_score ?? '',
          ra_verificada: companyInfo?.company_flags.is_verified ?? false,
          component: eventObject.componentLocation,
          area: eventObject.areaLocation,
        },
      },
    })
  }, [
    eventObject,
    companyInfo?.general_reputation?.average_score,
    companyInfo?.general_reputation?.status,
    companyInfo?.company_flags.is_verified,
    companyInfo?.name,
    companyInfo?.short_name,
  ])

  return (
    <S.Main>
      {!!(companyInfo && !isEmpty(companyInfo)) ? (
        reputation && (
          <>
            <S.SellerLogoNameContainer>
              {companyInfo!.logo_url ? (
                <img src={companyInfo!.logo_url} alt='seller-logo' />
              ) : (
                <S.StoreGenericAvatar>
                  <span>{companyInfo?.name.charAt(0)}</span>
                </S.StoreGenericAvatar>
              )}
              <Text color='steel' size='14px' fontWeight='bold'>
                {companyInfo?.name}
              </Text>
            </S.SellerLogoNameContainer>
            {companyInfo.company_flags.is_verified && <VerifyTag />}
            <S.Border isVerify={companyInfo.company_flags.is_verified}>
              <S.Header onClick={changeExpand}>
                <ReputationScore
                  expanded={expanded}
                  reputation={reputation}
                  average_score={companyInfo?.general_reputation?.average_score}
                />
              </S.Header>

              <S.SellerReputationDetail expanded={expanded}>
                <div>
                  <S.SellerReputationDescription
                    expanded={expanded}
                    bgColor={
                      handleNoIndexButVerify ? '#f8f3ff' : reputation.bgColor
                    }
                    color={reputation.text_color}
                  >
                    {handleNoIndexButVerify ? (
                      <S.ReputationDescriptionTitle>
                        Empresa verificada
                      </S.ReputationDescriptionTitle>
                    ) : null}
                    <Text
                      data-testid='reputation-description'
                      color='pickles'
                      size='14px'
                      fontWeight='600'
                      align='center'
                      margin='0'
                    >
                      {handleNoIndexButVerify
                        ? textNoIndexButVerify
                        : reputation.description}
                    </Text>
                  </S.SellerReputationDescription>

                  <a
                    href={companyInfo.ra_company_url}
                    onClick={understandReputation}
                    target='_blank'
                    rel='noreferrer'
                  >
                    <Icon
                      path={mdiPlusCircle}
                      color={light.colors.bowl}
                      size='12px'
                    />
                    <Text
                      color='bowl'
                      size='12px'
                      fontWeight='600'
                      align='center'
                    >
                      Entenda a reputação no Reclame AQUI
                    </Text>
                  </a>
                </div>
              </S.SellerReputationDetail>
              <S.HandleShowReport expanded={expanded}>
                <Report eventObject={eventObject} companyInfo={companyInfo} />
              </S.HandleShowReport>
            </S.Border>
          </>
        )
      ) : (
        <ReputationModalSkeleton />
      )}
    </S.Main>
  )
}

export default Reputation
