import {
  getChromeLocalData,
  setChromeLocalData,
} from 'hooks/chrome-storage-change-data'
import { useEffect, useState } from 'react'
import { ANONYMOUS_EXTENSION_PIN_CONFIG_SILENCE_DURATION_DEFAULT } from 'shared/cache'
import { PIN_CONFIG_SILENCE_WITHOUT_OFFERS_CACHE_NAME } from 'shared/pinConfigCache'
import { configurationOptionEventName, ConfigurationTriggerEventProps } from '.'
import { anonymousActionKeys, anonymousActionList } from './anonymous-helper'
import { Button } from './styles'

interface AnonymousOptionsProps {
  triggerEvent: (props: ConfigurationTriggerEventProps) => Promise<void>
  silencePin: (time: number) => void
  setActive: React.Dispatch<React.SetStateAction<boolean>>
}
function AnonymousOptions({
  setActive,
  silencePin,
  triggerEvent,
}: AnonymousOptionsProps) {
  const cacheName = PIN_CONFIG_SILENCE_WITHOUT_OFFERS_CACHE_NAME
  const [silenceWithoutOffersIsActive, setSilenceWithoutOffersIsActive] =
    useState()

  useEffect(() => {
    async function fn() {
      const localData = await getChromeLocalData(cacheName)
      setSilenceWithoutOffersIsActive(
        localData?.[cacheName] ? localData[cacheName] : false
      )
    }
    fn()
  }, [cacheName])

  const silenceEightHours = () => {
    silencePin(ANONYMOUS_EXTENSION_PIN_CONFIG_SILENCE_DURATION_DEFAULT)
  }

  const silenceWithoutOffers = async () => {
    const localData = await getChromeLocalData(cacheName)
    const oldValue = localData?.[cacheName] ? localData[cacheName] : false

    setActive(false)
    setChromeLocalData({
      [cacheName]: !oldValue,
    })
  }

  function action(key: string) {
    if (key === 'silence_eight_hours') return silenceEightHours

    if (key === 'silence_not_discount') return silenceWithoutOffers

    return undefined
  }

  return (
    <>
      {anonymousActionKeys.map((key) => (
        <Button
          active={
            key === 'silence_not_discount'
              ? silenceWithoutOffersIsActive
              : undefined
          }
          onClick={async () => {
            await triggerEvent({
              event: configurationOptionEventName,
              area: anonymousActionList[key].area,
            })
            action(key)?.()
          }}
        >
          {anonymousActionList[key].text}
        </Button>
      ))}
    </>
  )
}

export default AnonymousOptions
