import { mdiClose } from '@mdi/js'
import Icon from '@mdi/react'
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { useModal } from 'scripts/pin-component/hooks/ModalProvider/use'
import { PinState } from 'scripts/pin-component/models/pinState'
import { getCookie, setCookie } from 'utils/cookiesHelper'
import * as S from './styles'

import { OpenWith } from '@mui/icons-material'
import { EventAdapterTarget, eventAdapter } from 'adapter/event-adapter'
import { ComponentLocation } from 'domain/model/event'
import { useCompanyDiscounts } from 'scripts/pin-component/hooks/company-discounts'
import {
  PIN_CLOSED_SESSION_STORAGE_NAME,
  PIN_LOCALIZATION,
  PIN_STATE_COOKIE_LIFE_TIME,
  PIN_STATE_COOKIE_NAME,
  PIN_STATE_TIMER,
} from 'scripts/pin-component/shared/pinState'
import { VIEW_PIN_EVENT_SESSION } from 'shared/caches/event'
import { eventNamePrefix } from 'shared/gaEventsOrigin'
import { getPhrase } from 'utils/getPhrase'
import ClosePinGAEvent from './components/close-pin-ga-event'
import CouponsGAEvent from './components/coupons-ga-event'
import PinGAEvent from './components/pin-ga-event'
import ReputationGAEvent from './components/reputation-ga-event'
import { SVGBell, SVGCupons, SVGLogo } from './images'

let timer: NodeJS.Timeout

const Pin = () => {
  const {
    companyDiscounts,
    couponsQuantity,
    offersQuantity,
    couponsAndOffersQuantity,
  } = useCompanyDiscounts()
  const { openModalState, openCloseModal } = useModal()
  const [pinState, setPinState] = useState<PinState>()
  const [press, setPress] = useState<boolean>(false)
  const [hold, setHold] = useState<boolean>(false)
  const [localization, setLocalization] = useState<string>('300')

  const mainRef = useRef<HTMLBaseElement>(null)

  useEffect(() => {
    const viewPinSession = sessionStorage.getItem(VIEW_PIN_EVENT_SESSION)

    if (!viewPinSession && companyDiscounts) {
      eventAdapter({
        target: EventAdapterTarget.current,
        data: {
          event: `${eventNamePrefix}view_pin`,
          eventProps: {
            active_url: window.location.href,
            shortname: companyDiscounts.company_info?.short_name,
            company_name: companyDiscounts.company_info?.name,
            reputation:
              companyDiscounts.company_info.general_reputation?.status,
            score:
              companyDiscounts.company_info.general_reputation.average_score,
            ra_verificada: companyDiscounts.company_info.company_flags
              .is_verified
              ? true
              : false,
            total_discounts: couponsAndOffersQuantity,
            coupons: couponsQuantity,
            offers: offersQuantity,
            component: ComponentLocation.PIN,
          },
        },
      })
      sessionStorage.setItem(VIEW_PIN_EVENT_SESSION, 'true')
    }
  }, [
    companyDiscounts,
    couponsAndOffersQuantity,
    couponsQuantity,
    offersQuantity,
  ])

  const reputationInfo = useMemo(
    () =>
      companyDiscounts?.company_info.general_reputation?.status &&
      getPhrase(companyDiscounts?.company_info.general_reputation?.status),
    [companyDiscounts?.company_info.general_reputation?.status]
  )

  const showModal = useCallback(
    (event: any) => {
      event.preventDefault()
      event.stopPropagation()
      event.preventDefault()
      openCloseModal?.(!openModalState)
    },
    [openCloseModal, openModalState]
  )

  const clickInPin = (event: any) => {
    event.preventDefault()
    setPress(true)
  }
  const clickOutPin = useCallback(
    (event: any) => {
      event.preventDefault()
      if (!hold && press) {
        showModal(event)
      }
      setPress(false)
      setHold(false)
    },
    [hold, press, showModal]
  )

  const onMoveHandle = (event: any) => {
    event.preventDefault()
    let newLocalization = event.clientY - 20
    let limitWindowSize = window.innerHeight - 150

    if (hold && newLocalization < limitWindowSize && newLocalization > 50) {
      setLocalization(`${newLocalization}`)
      localStorage.setItem(PIN_LOCALIZATION, newLocalization.toString())
    }
  }

  useEffect(() => {
    const timer = setTimeout(() => {
      if (press) {
        setHold(true)
      }
    }, 300)

    return () => {
      clearTimeout(timer)
    }
  }, [hold, press])

  useEffect(() => {
    const closedSessionData = sessionStorage.getItem(
      PIN_CLOSED_SESSION_STORAGE_NAME
    )

    if (closedSessionData === 'closed') return

    const pinCookie = getCookie(PIN_STATE_COOKIE_NAME)

    if (pinCookie) return setPinState(PinState.SecondStart)

    setPinState(PinState.FirstStart)
    clearTimeout(timer)
    timer = setTimeout(() => {
      setPinState(PinState.SecondStart)
      setCookie(
        PIN_STATE_COOKIE_NAME,
        PinState.FirstStart,
        PIN_STATE_COOKIE_LIFE_TIME
      )
    }, PIN_STATE_TIMER)

    return () => clearTimeout(timer)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  useEffect(() => {
    const localStorageLocalization = localStorage.getItem(PIN_LOCALIZATION)
    if (localStorageLocalization) {
      setLocalization(localStorageLocalization)
    }
  }, [])

  return (
    <>
      {pinState === undefined ? (
        ''
      ) : (
        <S.Main
          ref={mainRef}
          state={pinState}
          holded={hold}
          localization={`${localization}px`}
          maxHeight={
            !!couponsAndOffersQuantity ||
            !!companyDiscounts?.company_info.main_segment?.title
              ? '118px'
              : '86px'
          }
          hasCupons={!!couponsAndOffersQuantity}
          onMouseDown={clickInPin}
          onMouseLeave={clickOutPin}
          onMouseUp={clickOutPin}
          onMouseMove={onMoveHandle}
        >
          <ClosePinGAEvent setPinState={setPinState} />
          <PinGAEvent pinState={pinState} openModalState={openModalState} />
          <ReputationGAEvent openModalState={openModalState} />
          <CouponsGAEvent openModalState={openModalState} />

          <S.SetPosition>
            <OpenWith
              style={{ fill: 'white', width: '30px', height: '30px' }}
            />
          </S.SetPosition>

          <S.CloseButton>
            <Icon path={mdiClose} size='12px' color='#000' />
          </S.CloseButton>

          {!!couponsAndOffersQuantity && (
            <S.Title state={pinState}>
              {`Encontramos ${couponsAndOffersQuantity}`}
              <br />
              {`cupo${couponsAndOffersQuantity > 1 ? 'ns' : 'm'} de desconto!`}
            </S.Title>
          )}

          {!couponsAndOffersQuantity && (
            <S.Title state={pinState}>
              {`Conheça o ranking`}
              <br />
              {`das melhores empresas`}
            </S.Title>
          )}

          <S.Logo>
            <SVGLogo />
          </S.Logo>

          {reputationInfo && (
            <S.Tag
              fontColor={reputationInfo.extension_score_color || ''}
              backgroundcolor='white'
            >
              <S.IconReputation src={`${reputationInfo.image}`} />
              {companyDiscounts?.company_info.general_reputation.average_score}
            </S.Tag>
          )}
          {!couponsAndOffersQuantity &&
            companyDiscounts?.company_info.main_segment && (
              <S.NotificationCircle showIcon={true}>
                <S.Icon>
                  <SVGBell></SVGBell>
                </S.Icon>
              </S.NotificationCircle>
            )}
          {!!couponsAndOffersQuantity && (
            <S.NotificationCircle showIcon={false}>
              <S.Icon>
                <SVGCupons></SVGCupons>
              </S.Icon>
              <p>{couponsAndOffersQuantity}</p>
            </S.NotificationCircle>
          )}
        </S.Main>
      )}
    </>
  )
}

export default Pin
