import { makeSinglePluralWord } from "utils/makeSinglePluralWord";

interface MakeTitleProps {
  length?: number;
  storeName?: string;
}
export const makeTitle = ({ length = 0, storeName }: MakeTitleProps) => (
  <>
    <span>({length})</span> Cupo{
      makeSinglePluralWord({ length: length, terms: ['m', 'ns'] })
    } e oferta{
      makeSinglePluralWord({ length: length, terms: ['', 's'] })
    } disponíve{
      makeSinglePluralWord({ length: length, terms: ['l', 'is'] })
    } {!!storeName && ` na ${storeName}`}
  </>
)
