import { IProfile } from 'hooks/Profile/state'
import { useCallback, useEffect, useMemo, useState } from 'react'
import { isEmpty } from 'utils/isEmpty'
import { useAnonymousRules } from './anonymousRules'
import { useSilencePin } from './silenceDuration'
import { useCompanyDiscounts } from '../company-discounts'

interface UseLoggedRulesProps {
  profile?: IProfile
}
export function useLoggedRules({ profile }: UseLoggedRulesProps) {
  const { couponsAndOffersQuantity } = useCompanyDiscounts()
  const [canShowPin, setCanShowPin] = useState(false)
  const { silencePin } = useSilencePin()
  const canShowPinAnonymousRules = useAnonymousRules()

  const hasCouponsAndOffers = useMemo(
    () => couponsAndOffersQuantity > 0,
    [couponsAndOffersQuantity]
  )

  const currentSiteIsBlocked = useCallback((domainList?: string[]) => {
    if (!domainList) return false

    const currentUrl = window.location.href

    if (isEmpty(domainList)) return false

    const filteredList = domainList.find((item) => currentUrl.includes(item))

    return !!filteredList
  }, [])

  useEffect(() => {
    if (profile && !isEmpty(profile)) {
      if (profile?.extension_pin_config?.disable_pin)
        return setCanShowPin(false)

      if (
        currentSiteIsBlocked(profile?.extension_pin_config?.blocked_domain_list)
      )
        return setCanShowPin(false)

      if (silencePin) return setCanShowPin(!silencePin)

      if (profile?.extension_pin_config?.show_only_stores_with_offers)
        return setCanShowPin(hasCouponsAndOffers)
    }

    setCanShowPin(canShowPinAnonymousRules)
  }, [
    profile,
    silencePin,
    hasCouponsAndOffers,
    canShowPinAnonymousRules,
    currentSiteIsBlocked,
  ])

  return canShowPin
}
