import styled, { css } from 'styled-components'
import CardProps from './props'

export const CardContainer = styled.div<CardProps>`
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: ${({justifyContent}) => justifyContent || 'center'};
  width: 100%;
  max-width: ${({ maxWidth }) => maxWidth ? maxWidth : 'auto'};
  max-height: ${({ maxHeight }) => maxHeight ? maxHeight : 'auto'};
  padding: ${({ padding }) => (padding ? padding : "12px 0")};
  border-radius: 8px;
  border: ${({ dashed, borderColor }) => {
    if (dashed) {
      return '1px dashed'
    }
    if (borderColor && !dashed) {
      return '1px solid'
    }
    return ''
  }};
  border-color: ${({ borderColor }) => (borderColor ? borderColor : null)};

  ${({
    backgroundColor,
    backgroundImage,
    gradient,
    gradientColorFrom,
    gradientColorTo,
    gradientAngle,
    gradientStart,
    gradientFinish
  }) => {
    if(backgroundImage && gradient){
      return css`
        background: url(${backgroundImage}) no-repeat right top, linear-gradient(${gradientAngle}deg, ${gradientColorFrom} ${gradientStart}%, ${gradientColorTo} ${gradientFinish}%); /* W3C */
      `
    }

    if (gradient) {
      return css`
        background: linear-gradient(${gradientAngle}deg, ${gradientColorFrom} ${gradientStart}%, ${gradientColorTo} ${gradientFinish}%)
      `
    }
    return css`background-color: ${backgroundColor}`
  }};

  background-size: ${({ backgroundSize }) => backgroundSize || 'inherit'};

  opacity: ${({ opacity }) => (opacity ? opacity : null)};
  box-shadow: ${({ shadow }) =>
    shadow ? '0px 2px 8px rgba(0, 0, 0, 0.1)' : null};

  &:hover {
    background-color: ${({ interactionEffect }) =>
      interactionEffect ? css`rgba(0, 0, 0, 0.04)` : null};
  }

  &:active {
    background-color: ${({ interactionEffect }) =>
      interactionEffect ? css`rgba(0, 0, 0, 0.12)` : null};
  }
`
