import { mdiAccountCircleOutline, mdiHomeOutline, mdiMagnify } from '@mdi/js'
import Icon from '@mdi/react'
import { EventAdapterTarget, eventAdapter } from 'adapter/event-adapter'
import {
  AreaLocation,
  ComponentLocation,
  EventOrigin,
} from 'domain/model/event'
import useAuth from 'hooks/auth/use'
import { useCallback } from 'react'
import { useLocation } from 'react-router-dom'
import { useCompanyDiscounts } from 'scripts/pin-component/hooks/company-discounts'
import useNotifications from 'scripts/pin-component/hooks/notifications/use'
import { eventNamePrefix } from 'shared/gaEventsOrigin'
import { getCurrentUrl } from 'utils/location/get-current-url'
import { NotificationIcon } from './NotificationIcon'
import { IconContainer as IconNavLink, Nav, WrapperContainer } from './styles'

const Footer = () => {
  const location = useLocation()
  const { companyDiscounts } = useCompanyDiscounts()
  const { notifications } = useNotifications()
  const { setFirstLogin } = useAuth()

  const eventTrigger = useCallback(
    async (area: string) => {
      const active_url = await getCurrentUrl(EventOrigin.PIN)

      const areaList: { [key: string]: AreaLocation } = {
        home: AreaLocation.HOME,
        coupons: AreaLocation.SEARCH,
        notifications: AreaLocation.NOTIFICATION,
        users: AreaLocation.PREFERENCES,
      }

      eventAdapter({
        target: EventAdapterTarget.current,
        data: {
          event: `${eventNamePrefix}navbar`,
          eventProps: {
            active_url,
            shortname: companyDiscounts?.company_info.short_name ?? '',
            company_name: companyDiscounts?.company_info.name ?? '',
            reputation:
              companyDiscounts?.company_info.general_reputation?.status ?? '',
            score:
              companyDiscounts?.company_info.general_reputation
                ?.average_score ?? '',
            ra_verificada:
              companyDiscounts?.company_info.company_flags.is_verified ?? false,
            component: ComponentLocation.MODAL_PIN,
            area: areaList[area],
          },
        },
      })
    },
    [
      companyDiscounts?.company_info.general_reputation?.average_score,
      companyDiscounts?.company_info.general_reputation?.status,
      companyDiscounts?.company_info.company_flags.is_verified,
      companyDiscounts?.company_info.name,
      companyDiscounts?.company_info.short_name,
    ]
  )

  return (
    <Nav id='navigation'>
      <WrapperContainer>
        <IconNavLink
          onClick={() => {
            eventTrigger('home')
            setFirstLogin(false)
          }}
          to='/home'
        >
          <Icon
            path={mdiHomeOutline}
            color={`${location.pathname === '/home' ? '#02793E' : '#4B5963'}`}
          />
        </IconNavLink>

        <IconNavLink
          onClick={() => {
            eventTrigger('coupons')
            setFirstLogin(false)
          }}
          to='/coupons'
        >
          <Icon
            path={mdiMagnify}
            color={`${
              location.pathname === '/coupons' ? '#02793E' : '#4B5963'
            }`}
          />
        </IconNavLink>

        <IconNavLink
          onClick={() => {
            eventTrigger('notifications')
            setFirstLogin(false)
          }}
          to='/notification'
        >
          <NotificationIcon
            fill={location.pathname === '/notification' ? '#02793E' : '#4B5963'}
            hasNotifications={notifications?.length > 0}
          />
        </IconNavLink>

        <IconNavLink
          onClick={() => {
            eventTrigger('users')
          }}
          to='/users'
        >
          <Icon
            path={mdiAccountCircleOutline}
            color={`${location.pathname === '/users' ? '#02793E' : '#4B5963'}`}
          />
        </IconNavLink>
      </WrapperContainer>
    </Nav>
  )
}

export default Footer
