import { ON_FOCUS_CACHE_NAMES } from 'scripts/background-listeners/on-focus-listener'
import { getContentScriptCurrentUrl } from './location/get-content-script-current-url'
import { getItemFromCache } from './cacheUtils'

export const isSamePageOrigin = (storeUrl?: string) => {
  const { shortSubdomainExtracted } = getContentScriptCurrentUrl()

  if (!storeUrl) return false

  return shortSubdomainExtracted === storeUrl
}

type IsSameActiveTabOriginProps = {
  path?: string
  ra_path?: string
}
export const isSameActiveTabOrigin = async ({
  path,
  ra_path,
}: IsSameActiveTabOriginProps) => {
  const data = await getItemFromCache<number>(
    ON_FOCUS_CACHE_NAMES.FOCUSED_WINDOW_ID
  )

  if ((!path && !ra_path) || !data) return false

  const tabs = await chrome.tabs.query({
    active: true,
    windowId: data,
  })

  return tabs.find(
    (tab) =>
      (path && tab?.url?.includes(path.toLowerCase())) ||
      (ra_path && tab?.url?.includes(ra_path.toLowerCase()))
  )
}
