import { useChromeStorageLocal } from 'hooks/chrome-storage-listener'
import { useEffect, useMemo, useState } from 'react'
import { PIN_CONFIG_SILENCE_WITHOUT_OFFERS_CACHE_NAME } from 'shared/pinConfigCache'
import { KEEP_SHOW_PIN } from 'shared/storageNames'
import { useSilencePin } from './silenceDuration'
import { useCompanyDiscounts } from '../company-discounts'
import { isEmpty } from 'utils/isEmpty'
import { DiscountsApiResponseWithPath } from 'domain/model/discounts/main'

export function useAnonymousRules() {
  const { currentData: pinSilenceWithoutOffersStorage } = useChromeStorageLocal(
    PIN_CONFIG_SILENCE_WITHOUT_OFFERS_CACHE_NAME
  )
  const [canShowPin, setCanShowPin] = useState(false)
  const { companyDiscounts, couponsAndOffersQuantity } = useCompanyDiscounts()
  const { silencePin } = useSilencePin()

  const hasCouponsAndOffers = useMemo(
    () => couponsAndOffersQuantity > 0,
    [couponsAndOffersQuantity]
  )

  const hasCompanyData = (data?: DiscountsApiResponseWithPath | null) =>
    data && !isEmpty(data)

  useEffect(() => {
    if (silencePin) return setCanShowPin(!silencePin)

    if (pinSilenceWithoutOffersStorage)
      return setCanShowPin(hasCouponsAndOffers)

    if (companyDiscounts?.company_info.company_flags.hide_pin)
      return setCanShowPin(false)

    const keepShowPin = sessionStorage.getItem(KEEP_SHOW_PIN)

    setCanShowPin(hasCompanyData(companyDiscounts) || !!keepShowPin)
  }, [
    hasCouponsAndOffers,
    pinSilenceWithoutOffersStorage,
    silencePin,
    companyDiscounts,
  ])

  return canShowPin
}
