import { Tooltip } from '@mui/material'
import { useCallback, useMemo, useState } from 'react'
import { getRegexUrl } from 'utils/urlRegex'
import { Dialog } from '../../Dialog'
import { blockedDomainList } from '../../Preferences/Pin/helper'
import * as S from './styles'

interface ListOptionProps {
  text: string
  list: any[]
  validation?: () => RegExp
  dataExtractor?: () => RegExp
  handleChange: (type: 'add' | 'remove', value: string) => void
}
function ListOption({
  text,
  list,
  validation,
  dataExtractor,
  handleChange,
}: ListOptionProps) {
  const [openAddSite, setOpenAddSite] = useState(false)
  const [openList, setOpenList] = useState(false)

  const [site, setSite] = useState('')
  const [canSave, setCanSave] = useState(false)

  const dialogTitle = useMemo(() => {
    if (openList) return 'Lista de sites adicionados'

    if (openAddSite)
      return 'Adicione a url (link) do site que você não gostaria que a janela flutuante mostre:'

    return ''
  }, [openAddSite, openList])

  const dialogClose = useCallback(() => {
    openAddSite && setOpenAddSite(false)
    openList && setOpenList(false)
    setSite('')
    setCanSave(false)
  }, [openAddSite, openList])

  const addSite = useCallback(() => {
    const extractedData = dataExtractor
      ? getRegexUrl.execRule({
          rule: dataExtractor(),
          url: site,
        })
      : null

    dialogClose()
    handleChange?.('add', extractedData ?? site)
  }, [dataExtractor, dialogClose, handleChange, site])

  return (
    <S.Main>
      <S.Title>{text}</S.Title>

      <S.Actions>
        {blockedDomainList.map(({ id, icon, tooltip, type }) => (
          <li key={id}>
            <Tooltip title={tooltip}>
              <S.ActionButton
                id={id}
                onClick={() => {
                  type === 'add' && setOpenAddSite(true)
                  type === 'list' && setOpenList(true)
                }}
              >
                {icon}
              </S.ActionButton>
            </Tooltip>
          </li>
        ))}
      </S.Actions>

      <Dialog
        canSave={canSave}
        dialogTitle={dialogTitle}
        list={list}
        openAdd={openAddSite}
        openList={openList}
        inputValue={site}
        inputLabel='Adicionar site'
        addValue={addSite}
        setInputValue={setSite}
        setCanSave={setCanSave}
        inputValueIsValid={(value) => validation?.().test(value) ?? true}
        dialogClose={dialogClose}
        handleChange={handleChange}
      />
    </S.Main>
  )
}

export default ListOption
