export const SellerReputationDetail = styled.div<IExpanded>`
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  border-top: ${({ expanded, theme }) =>
    expanded && `1px solid ${theme.colors.iron}`};
  border-bottom: ${({ expanded, theme }) =>
    expanded && `1px solid ${theme.colors.iron}`};
  padding: ${({ expanded }) => expanded && '16px 0px 7px'};

  & > div:first-child {
    width: 100%;
    height: 100%;
    max-height: ${({ expanded }) => (expanded ? '150px' : '0')};
    transform: ${({ expanded }) => (expanded ? 'scaleY(1)' : 'scaleY(0)')};
    transition: transform 0.7s ease-in-out,
      max-height 0.7s cubic-bezier(0.42, 0, 0.58, 1);

    & > a {
      margin: 12px auto;
      text-decoration: none;
      width: 100%;
      min-width: 248px;
      max-width: 248px;

      display: flex;
      align-items: center;
      justify-content: center;
      gap: 4px;

      opacity: ${({ expanded }) => (expanded ? 1 : 0)};
      transform: ${({ expanded }) =>
        expanded ? 'translateY(-10%)' : 'translateY(0)'};

      transition: opacity 1s, transform 1s;
    }
  }
`

const ShowDescriptionAnimation = keyframes`
  0% {
    transform: translateX(100%);
    opacity: 0;
  }
  100% {
    transform: translateX(0);
    opacity: 1;
  }
`

const HideDescriptionAnimation = keyframes`
  0% {
    transform: translateX(0);
    opacity: 1;
  }
  100% {
    transform: translateX(100%);
    opacity: 0;
  }
`

interface ISellerReputationDescription extends IExpanded {
  bgColor?: string
  color?: string
}
export const SellerReputationDescription = styled.div<ISellerReputationDescription>`
  background-color: ${({ bgColor, theme }) =>
    bgColor ? bgColor : theme.colors.thousand};
  border-radius: 8px;
  padding: 16px;
  margin: 2px 6px;

  width: 100%;
  max-width: -webkit-fill-available;
  height: auto;

  transform: translateX(100%);
  opacity: 0;

  > p {
    color: ${({ color, theme }) => (color ? color : theme.colors.thousand)};
  }

  animation-name: ${({ expanded }) =>
    expanded ? ShowDescriptionAnimation : HideDescriptionAnimation};
  animation-duration: 1s;
  animation-fill-mode: forwards;
`
