import { EventAdapterTarget, eventAdapter } from 'adapter/event-adapter'
import { NoHasDiscountsProps } from 'components/NoHasDiscounts'
import { useCompanyDiscounts } from 'scripts/pin-component/hooks/company-discounts'
import { eventNamePrefix } from 'shared/gaEventsOrigin'
import * as S from './styles'

const CtaDiscountPage: React.FC<NoHasDiscountsProps> = ({
  eventObject,
  reputationValid,
}) => {
  const { company_info } = useCompanyDiscounts().companyDiscounts || {}

  const getNameMixPanelEvent = () => {
    return company_info?.main_segment
      ? 'segment_cta'
      : 'segment_cta_no_discounts'
  }

  const handleMixPanelEvents = () => {
    eventAdapter({
      target: EventAdapterTarget.current,
      data: {
        event: `${eventNamePrefix}${getNameMixPanelEvent()}`,
        eventProps: {
          active_url: window.location.href,
          shortname: company_info?.short_name ?? '',
          company_name: company_info?.name ?? '',
          reputation: company_info?.general_reputation?.status ?? '',
          score: company_info?.general_reputation?.average_score ?? '',
          ra_verificada: company_info?.company_flags?.has_verificada ?? false,
          component: 'modal_pin',
          main_segment: company_info?.main_segment?.title ?? '',
          secondary_segment: company_info?.secondary_segments
            ? company_info?.secondary_segments[0].title
            : 'null',
        },
      },
    })
  }

  const makeUrl = () => {
    const baseUrl = process.env.REACT_APP_REDIRECT_RA_URL
    const mainSegment = company_info?.main_segment?.shortname
    const secondarySegment = company_info?.secondary_segments?.[0]?.shortname

    const segmentPath =
      mainSegment && secondarySegment
        ? `/${mainSegment}/${secondarySegment}`
        : ''

    return `${baseUrl}/segmentos${segmentPath}`
  }

  return (
    <S.Box>
      <S.BannerTitle>
        Conheça o ranking das melhores empresas do segmento{' '}
        {company_info?.secondary_segments?.[0]?.title ?? ''}
      </S.BannerTitle>
      <S.ButtonDiscounts
        target='_blank'
        href={makeUrl()}
        onClick={() => handleMixPanelEvents()}
      >
        Ver empresas
      </S.ButtonDiscounts>
    </S.Box>
  )
}

export default CtaDiscountPage
