import { useEffect, useState } from 'react'
import { useProfile } from 'scripts/pin-component/hooks/profile/use'
import { useLoggedRules } from './loggedRules'

interface UseCanShowPinProps {
  isDangerous?: boolean
  windowIsPopup?: boolean
}

export function useCanShowPin({
  isDangerous,
  windowIsPopup,
}: UseCanShowPinProps) {
  const [showPin, setShowPin] = useState(false)
  const { cachedProfile } = useProfile()
  const canShowPinLoggedRules = useLoggedRules({
    profile: cachedProfile?.profile,
  })

  useEffect(() => {
    if (windowIsPopup !== undefined)
      setShowPin(windowIsPopup || isDangerous ? false : canShowPinLoggedRules)
  }, [
    canShowPinLoggedRules,
    cachedProfile,
    showPin,
    isDangerous,
    windowIsPopup,
  ])

  return showPin
}
