import { useCallback, useMemo } from 'react'
import { useUpdatePinConfig } from 'scripts/pin-component/hooks/preferences/use-update-pin-config'
import { useProfile } from 'scripts/pin-component/hooks/profile/use'
import { ConfigurationTriggerEventProps, configurationOptionEventName } from '.'
import { getContentScriptCurrentUrl } from 'utils/location/get-content-script-current-url'
import { LOGGED_EXTENTION_PIN_CONFIG_SILENCE_DURATION_TWENTY_FOUR_HOURS } from 'shared/cache'
import { Button } from './styles'
import { loggedActionKeys, loggedActionList } from './logged-helper'

interface LoggedOptionsProps {
  triggerEvent: (props: ConfigurationTriggerEventProps) => Promise<void>
  silencePin: (time: number) => void
  setActive: React.Dispatch<React.SetStateAction<boolean>>
}

function LoggedOptions({
  triggerEvent,
  silencePin,
  setActive,
}: LoggedOptionsProps) {
  const { handleUpdatePinConfig } = useUpdatePinConfig()
  const { cachedProfile } = useProfile()
  const { extractedSubdomainUrl } = getContentScriptCurrentUrl()

  const handleSilencePinLogged = useCallback(() => {
    silencePin(LOGGED_EXTENTION_PIN_CONFIG_SILENCE_DURATION_TWENTY_FOUR_HOURS)
    setActive(false)
  }, [setActive, silencePin])

  const silenceWithoutOffersLogged = useCallback(() => {
    handleUpdatePinConfig({
      paramName: 'show_only_stores_with_offers',
      value:
        !cachedProfile?.profile?.extension_pin_config
          ?.show_only_stores_with_offers,
    })
    setActive(false)
  }, [
    cachedProfile?.profile?.extension_pin_config?.show_only_stores_with_offers,
    handleUpdatePinConfig,
    setActive,
  ])

  const handleSilenceSite = useCallback(() => {
    const currentList =
      cachedProfile?.profile?.extension_pin_config?.blocked_domain_list ?? []

    if (!currentList.includes(extractedSubdomainUrl)) {
      let newList: string[] = [...currentList, extractedSubdomainUrl]

      handleUpdatePinConfig({
        paramName: 'blocked_domain_list',
        value: newList,
      })
    }

    setActive(false)
  }, [
    cachedProfile?.profile?.extension_pin_config?.blocked_domain_list,
    extractedSubdomainUrl,
    handleUpdatePinConfig,
    setActive,
  ])

  const profileBlockedSite = useMemo(() => {
    const currentList =
      cachedProfile?.profile?.extension_pin_config?.blocked_domain_list ?? []

    return currentList.includes(extractedSubdomainUrl)
  }, [
    cachedProfile?.profile?.extension_pin_config?.blocked_domain_list,
    extractedSubdomainUrl,
  ])

  const onlyStoreWithOffers = useMemo(() => {
    return cachedProfile?.profile?.extension_pin_config
      ?.show_only_stores_with_offers
  }, [
    cachedProfile?.profile?.extension_pin_config?.show_only_stores_with_offers,
  ])

  function isActive(key: string) {
    if (key === 'silence_site') return profileBlockedSite

    if (key === 'silence_not_discount') return onlyStoreWithOffers

    return undefined
  }

  function action(key: string) {
    if (key === 'silence_twenty_four') return handleSilencePinLogged

    if (key === 'silence_site') return handleSilenceSite

    if (key === 'silence_not_discount') return silenceWithoutOffersLogged

    return undefined
  }

  return (
    <>
      {loggedActionKeys.map((key) => (
        <Button
          active={isActive(key)}
          onClick={async () => {
            await triggerEvent({
              event: configurationOptionEventName,
              area: loggedActionList[key].area,
            })
            action(key)?.()
          }}
        >
          {loggedActionList[key].text}
        </Button>
      ))}
    </>
  )
}

export default LoggedOptions
