import Global from 'styles/global-reset'

import Container from 'components/Container'
import Login from 'components/Login'
import {
  AreaLocation,
  ComponentLocation,
  EventOrigin,
} from 'domain/model/event'
import useAuth from 'hooks/auth/use'
import SuccessLogin from 'pages/User/pages/SuccessLogin'
import { useCompanyDiscounts } from 'scripts/pin-component/hooks/company-discounts'
import { useProfile } from 'scripts/pin-component/hooks/profile/use'
import * as C from './components'
import * as S from './styles'

const User: React.FC = () => {
  const { isAuthenticated, firstLogin } = useAuth()
  const { cachedProfile } = useProfile()
  const { companyDiscounts } = useCompanyDiscounts()

  return (
    <Container minHeight='400px' gap='0px'>
      <Global />
      {isAuthenticated && firstLogin ? (
        <SuccessLogin
          companyInfo={companyDiscounts?.company_info}
          eventObject={{
            eventOrigin: EventOrigin.PIN,
            componentLocation: ComponentLocation.MODAL_PIN,
            areaLocation: AreaLocation.PREFERENCES,
          }}
        />
      ) : isAuthenticated && !firstLogin ? (
        <S.Content>
          <S.Config>
            <S.ConfigTitle>Central de preferências</S.ConfigTitle>
            {cachedProfile?.profile?.extension_pin_config?.disable_pin ? (
              <C.PinDisabledWarning />
            ) : null}
            <C.PreferencesPin />
            <C.PreferencesMain />
            <C.PreferencesFooter />
          </S.Config>
        </S.Content>
      ) : (
        <Login
          companyInfo={companyDiscounts?.company_info}
          eventObject={{
            eventOrigin: EventOrigin.PIN,
            componentLocation: ComponentLocation.MODAL_PIN,
            areaLocation: AreaLocation.PREFERENCES,
          }}
        />
      )}
    </Container>
  )
}

export default User
