import { useAlert } from 'hooks/AlertProvider/use'
import {
  setChromeLocalData,
  setChromeSyncData,
} from 'hooks/chrome-storage-change-data'
import { useChromeStorageLocal } from 'hooks/chrome-storage-listener'
import { ReactNode, useEffect, useState } from 'react'
import {
  IS_IDENTIFIED,
  IS_IDENTIFIED_PIN,
  REMOVE_IDENTIFY,
  REMOVE_IDENTIFY_PIN,
} from 'shared/caches/event'
import { extractExpireTime } from 'utils/auth-token'
import { isDateExpired } from 'utils/dateHelper'
import AuthContext from './context'
import { ILogin } from './state'

interface AuthProviderProps {
  children: ReactNode
}

interface IToken {
  access_token: string
}

const AuthProvider = ({ children }: AuthProviderProps) => {
  const { currentData: storageToken } = useChromeStorageLocal<string>('token')
  const [firstLogin, setFirstLogin] = useState<boolean>(false)
  const [error, setError] = useState(false)
  const [loading, setLoading] = useState(false)
  const isAuthenticated = !!storageToken
  const { openAlert } = useAlert()

  useEffect(() => {
    const token: IToken = storageToken ? JSON.parse(storageToken) : undefined
    const expireIn = extractExpireTime(token?.access_token)

    if (expireIn && isDateExpired(expireIn)) {
      logout()
    }
  }, [storageToken])

  async function login({ password, user }: ILogin) {
    setLoading(true)

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL}/login`, {
        method: 'POST',
        body: JSON.stringify({
          password,
          username: user,
        }),
      })

      if (response.status === 401)
        openAlert?.({
          title: 'Ops! Dados não conferem.',
          message: 'Revise os campos e tente novamente!',
          severity: 'error',
        })

      if (response.status !== 200 && response.status !== 401)
        throw new Error('Erro ao realizar login! Tente novamente mais tarde.')

      const data: IToken | undefined = await response.json()

      if (data?.access_token) {
        await setChromeLocalData({
          [IS_IDENTIFIED]: false,
          [IS_IDENTIFIED_PIN]: false,
        })

        const expireIn = extractExpireTime(data?.access_token)

        await setChromeLocalData({
          token: JSON.stringify({
            access_token: data?.access_token,
            expire_in: expireIn,
          }),
        })
      }

      setFirstLogin(true)
      setError(false)
      setLoading(false)
    } catch (error: any) {
      openAlert?.({
        title: 'Erro',
        message: error?.message ?? 'Erro inexperado',
        severity: 'error',
      })

      setError(true)
      setLoading(false)
    }
  }

  const logout = async () => {
    await setChromeLocalData({
      [IS_IDENTIFIED]: false,
      [REMOVE_IDENTIFY]: true,
      [IS_IDENTIFIED_PIN]: false,
      [REMOVE_IDENTIFY_PIN]: true,
      token: null,
    })
    await setChromeSyncData({ profile: null })
  }

  const state = {
    isAuthenticated,
    firstLogin,
    setFirstLogin,
    token: storageToken ? JSON.parse(storageToken) : undefined,
    logout,
    login,
    loading,
    error,
  }

  return <AuthContext.Provider value={state}>{children}</AuthContext.Provider>
}

export default AuthProvider
