import { EventAdapterTarget, eventAdapter } from '..'

export enum FooterEventIds {
  'avalie-nossa-extensao' = 'rate',
  'termos-de-uso' = 'terms_of_use',
  'sair-da-extensao' = 'logout',
}

export const footerEventLinks = {
  rate: 'https://chrome.google.com/webstore/detail/reclameaqui%2B/fhamhppabjaafimidmelnmpfangjdnhj',
  terms_of_use: 'https://mais.reclameaqui.com.br/termos-de-uso',
  logout: undefined,
}

interface EventPreferencesFooterAdapterProps {
  id: keyof typeof FooterEventIds
  eventProps?: any
}
export function getFooterData({
  id,
  eventProps,
}: EventPreferencesFooterAdapterProps) {
  const event = FooterEventIds[id]
  const footerLink = footerEventLinks[event]

  return {
    target: EventAdapterTarget.current,
    data: {
      event: event,
      eventProps: footerLink ? { ...eventProps, link: footerLink } : eventProps,
    },
  }
}

export function eventPreferencesFooterAdapter(
  data: EventPreferencesFooterAdapterProps
) {
  const footerData = getFooterData(data)
  eventAdapter(footerData)
}
