import { Check } from '@mui/icons-material'
import { EventAdapterTarget, eventAdapter } from 'adapter/event-adapter'
import { DiscountsCompanyInfo } from 'domain/model/discounts/discounts-company-info'
import { Discount } from 'domain/model/discounts/main'
import { EventObject } from 'domain/model/event'
import { DiscountsService } from 'domain/services/discounts'
import { AffiliateParamService } from 'domain/services/ParamService/Affiliate/affiliateParamService'
import { CuponeriaParamService } from 'domain/services/ParamService/Cuponeria/cuponeriaParamServiceParams'
import React, { useState } from 'react'
import { eventNamePrefix } from 'shared/gaEventsOrigin'
import { getCurrentUrl } from 'utils/location/get-current-url'
import openRedirectPage from 'utils/openRamaisRedirectPage'
import * as S from './styles'

interface CouponEventObject extends EventObject {
  position: number
  totalDiscounts: number
}

interface CouponProp {
  companyInfo: DiscountsCompanyInfo
  coupon: Discount
  storePath: string
  eventObject: CouponEventObject
}

const CouponCard: React.FC<CouponProp> = ({
  companyInfo,
  coupon,
  storePath,
  eventObject,
}) => {
  const [showRules, setShowRules] = useState(false)
  const [areClicked, setAreClicked] = useState(false)

  const toggleRules = async () => {
    const active_url = await getCurrentUrl(eventObject.eventOrigin)

    if (!showRules)
      eventAdapter({
        target: EventAdapterTarget.current,
        data: {
          event: `${eventNamePrefix}coupon_rules`,
          eventProps: {
            active_url,
            shortname: companyInfo.short_name,
            company_url: storePath,
            position: eventObject.position,
            total_discounts: eventObject.totalDiscounts,
            component: eventObject.componentLocation,
            area: eventObject.areaLocation,
          },
        },
      })

    setShowRules(!showRules)
  }

  const copyCode = async () => {
    const response = await DiscountsService.getRedirectUrl(coupon.id)

    if (response?.code) {
      await navigator.clipboard.writeText(response?.code)
      setAreClicked(true)
    }

    const active_url = await getCurrentUrl(eventObject.eventOrigin)

    eventAdapter({
      target: EventAdapterTarget.current,
      data: {
        event: `${eventNamePrefix}copy_coupon`,
        eventProps: {
          active_url,
          is_vcmo: coupon?.is_vcmo ?? false,
          shortname: companyInfo?.short_name ?? '',
          company_name: companyInfo?.name ?? '',
          company_url: storePath ?? '',
          reputation: companyInfo?.general_reputation?.status ?? '',
          score: companyInfo?.general_reputation?.average_score ?? '',
          ra_verificada: companyInfo.company_flags.is_verified ?? false,
          coupon_code: response?.code,
          coupon_title: coupon?.title ?? '',
          coupon_rules: coupon?.description ?? '',
          position: eventObject.position,
          total_discounts: eventObject.totalDiscounts,
          component: eventObject.componentLocation,
          area: eventObject.areaLocation,
        },
      },
    })

    if (response?.link && response) {
      const paramService =
        response.discount_source === 'CP'
          ? new CuponeriaParamService({
              url: response.link,
              value: 'reclame-aqui-ext',
            })
          : new AffiliateParamService({
              url: response.link,
              affiliateId: response.affiliate,
              value: 'ext',
            })

      const redirectUrl = paramService.get()

      openRedirectPage({
        url: redirectUrl,
        code: response?.code,
        seller: companyInfo.name,
        sellerReputation: companyInfo.general_reputation,
        sellerLogoUrl: companyInfo.logo_url,
      })
      return
    }

    openRedirectPage({
      url: `https://${storePath}`,
      code: response?.code,
      seller: companyInfo.name,
      sellerReputation: companyInfo.general_reputation,
      sellerLogoUrl: companyInfo.logo_url,
    })
  }

  return (
    <S.Main>
      <S.Header>
        <S.Title>{coupon?.title ? coupon.title : coupon.description}</S.Title>
        <S.CopyButtonOutside click={areClicked}>
          <S.CopyButton
            data-testid='copy-button'
            click={areClicked}
            onClick={copyCode}
          >
            {areClicked ? 'Cupom copiado' : 'Copiar e ir para loja'}
            {areClicked && (
              <S.Icon>
                {' '}
                <Check />{' '}
              </S.Icon>
            )}
          </S.CopyButton>
          <S.TextButton>
            {' '}
            {coupon?.code ?? `CUPOM${new Date().getFullYear()}`}{' '}
          </S.TextButton>
        </S.CopyButtonOutside>
      </S.Header>
      <S.Line />
      <S.RulesContainer>
        <S.RulesHeader data-testid='rules-button' onClick={toggleRules}>
          <S.RuleTitle>Regras do cupom</S.RuleTitle>
          <S.ArrowIcon active={showRules} />
        </S.RulesHeader>
        {showRules && (
          <S.RulesDescription data-testid='rules-description'>
            {coupon.description}
          </S.RulesDescription>
        )}
      </S.RulesContainer>
    </S.Main>
  )
}

export default CouponCard
