import { createContext, useCallback, useEffect, useState } from 'react'
import { DiscountsSummaryContextProps } from './state'
import { DiscountsSummaryApiResponse } from 'domain/model/discounts/main'

const DISCOUNTS_SUMMARY_CACHE_NAME =
  'reclameaqui_extension_pin_discounts_summary'

export const DiscountsSummaryContext =
  createContext<DiscountsSummaryContextProps>({
    loading: false,
  })

interface DiscountsSummaryProviderProps {
  children: any
}
const DiscountsSummaryProvider = ({
  children,
}: DiscountsSummaryProviderProps) => {
  const [discountsSummary, setDiscountsSummary] =
    useState<DiscountsSummaryApiResponse[]>()
  const [loading, setLoading] = useState(false)

  const getDiscountsSummary = useCallback(() => {
    setLoading(true)
    const response = sessionStorage.getItem(DISCOUNTS_SUMMARY_CACHE_NAME)

    if (response) {
      setLoading(false)
      return setDiscountsSummary(JSON.parse(response))
    }

    chrome.runtime.sendMessage(
      { name: 'GET_DISCOUNTS_SUMMARY' },
      (response) => {
        sessionStorage.setItem(
          DISCOUNTS_SUMMARY_CACHE_NAME,
          JSON.stringify(response)
        )
        setDiscountsSummary(response)
      }
    )

    setLoading(false)
    setDiscountsSummary([])
  }, [])

  useEffect(() => {
    getDiscountsSummary?.()
  }, [getDiscountsSummary])

  return (
    <DiscountsSummaryContext.Provider
      value={{
        loading,
        discountsSummary,
        getDiscountsSummary,
      }}
    >
      {children}
    </DiscountsSummaryContext.Provider>
  )
}

export default DiscountsSummaryProvider
