import { CompleteUrl } from '../completeUrl';

import { UrlService } from '../urlService';

interface CuponeriaParamServiceParams {
  url: string;
  value: string;
}
export class CuponeriaParamService {
  private url: string;

  private value: string;

  constructor({ url, value }: CuponeriaParamServiceParams) {
    this.url = url;
    this.value = value;
  }

  get() {
    const urlService = new UrlService(this.url);
    const completeUrl = new CompleteUrl(
      {
        prefix: 'utm_source',
        value: this.value,
      },
      urlService,
    );

    return completeUrl.get();
  }
}
