import { useChromeStorageSync } from 'hooks/chrome-storage-listener'
import { useContext } from 'react'
import { ProfileContext } from './context'
import { CachedProfile } from './state'

export const useProfile = () => useContext(ProfileContext)

const PROFILE_SETTINGS_KEY = 'profile'

export const useSyncProfile = () =>
  useChromeStorageSync<CachedProfile>(PROFILE_SETTINGS_KEY)
